const DATA={"tracks":[{"id":"JES","name":"사복음서","description":"예수님의 생애·말씀·십자가·부활","order":0},{"id":"ACT","name":"사도행전","description":"부활하신 주님과 성령의 역사","order":1},{"id":"EPI","name":"신약 서신과 나머지 신약","description":"로마서 → 히브리서 → 나머지 신약","order":2},{"id":"PSA","name":"시편 기도 묵상","description":"탄식에서 신뢰와 찬양까지","order":3},{"id":"OTN","name":"구약 묵상","description":"예레미야부터 말씀을 따라 읽기","order":4}],"index":[{"id":"INT-001","track":"JES","title":"구유에 누이신 구주","passage":"눅 2:1–20","sequence":1,"phase":"INTRO","available":true,"doc":"https://docs.google.com/document/d/1xi7AyN0haCf1K8uw1VBM4ZBBr0Gs6KINXd9yvqss4WI/edit"},{"id":"INT-002","track":"JES","title":"기다리던 구원을 품에 안다","passage":"눅 2:21–40","sequence":2,"phase":"INTRO","available":false,"doc":"https://docs.google.com/document/d/1z5nt4UUKx3klpaUb5NPF7RKnUAc7vlnkBrvSJu82llc/edit"},{"id":"INT-003","track":"JES","title":"동방에서 찾아온 경배자들","passage":"마 2:1–12","sequence":3,"phase":"INTRO","available":false,"doc":"https://docs.google.com/document/d/1npIQ-b3XRzLabFT_TTXEXLMbqft5cMRwfSfLZV-gpRM/edit"},{"id":"INT-004","track":"JES","title":"위협 속에서 지켜진 아기 예수님","passage":"마 2:13–23","sequence":4,"phase":"INTRO","available":false,"doc":"https://docs.google.com/document/d/1xyxZKCYTAZdegoBFltVboPwPsqTb9wR2vNpes30kjvQ/edit"},{"id":"INT-005","track":"JES","title":"내 아버지께 속한 곳에 있어야 합니다","passage":"눅 2:41–52","sequence":5,"phase":"INTRO","available":false,"doc":"https://docs.google.com/document/d/1gDswh81V9gDyh_8wZvfdCj2eNC8_4F3JA89EHo7oKjk/edit"},{"id":"JES-001","track":"JES","title":"세례 받으시는 하나님의 아들","passage":"마 3:13–17","sequence":1,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1mHvJDskKPRTwTj2SKhtgnu65wUHY0oVCett0zsgMBn8/edit"},{"id":"JES-002","track":"JES","title":"광야에서 신실하신 아들","passage":"마 4:1–11","sequence":2,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1q1bbO5AfCl8PiuG6VivnfAPR_G14HUq6Wt_40MWKMnA/edit"},{"id":"JES-003","track":"JES","title":"와서 보라","passage":"요 1:35–51","sequence":3,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1H0JRt2RLXHWax3mgy0-JdRrG7Q3l1_D4vjrXC3vCj3g/edit"},{"id":"JES-004","track":"JES","title":"혼인 잔치에 계신 예수님","passage":"요 2:1–12","sequence":4,"phase":"MAIN","available":false,"doc":""},{"id":"JES-005","track":"JES","title":"성전에서 보이신 예수님의 열심","passage":"요 2:13–25","sequence":5,"phase":"MAIN","available":false,"doc":""},{"id":"JES-006","track":"JES","title":"밤에 찾아온 니고데모","passage":"요 3:1–21","sequence":6,"phase":"MAIN","available":false,"doc":""},{"id":"JES-007","track":"JES","title":"우물가의 여인과 예수님","passage":"요 4:1–26","sequence":7,"phase":"MAIN","available":false,"doc":""},{"id":"JES-008","track":"JES","title":"나의 양식은 아버지의 뜻을 행하는 것","passage":"요 4:27–42","sequence":8,"phase":"MAIN","available":false,"doc":""},{"id":"JES-009","track":"JES","title":"말씀만으로 고치시는 예수님","passage":"요 4:43–54","sequence":9,"phase":"MAIN","available":false,"doc":""},{"id":"JES-PILOT-LK05","track":"JES","title":"예수님은 왜 죄인에게 떠나지 않으셨는가?","passage":"눅 5:1–11","sequence":900,"phase":"PILOT","available":true,"doc":"https://docs.google.com/document/d/1q50SR-8bb8aqBaPIQNJ6LN-2j7QesfwA28evbS_8kAQ/edit"},{"id":"ACT-001","track":"ACT","title":"떠나신 것이 끝이 아닙니다","passage":"행 1:1–11","sequence":1,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1e20rdGLVdxcxAgqXnbveAJFgTeUlTq1M0Dd3uDFbIVA/edit"},{"id":"ACT-002","track":"ACT","title":"말씀을 붙들고 기다리는 제자들","passage":"행 1:12–26","sequence":2,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1gpHnqdaYMUIMhEjapUWVqERhRCrZdikN2MR5HmSzkeY/edit"},{"id":"ACT-003","track":"ACT","title":"성령이 오신 날","passage":"행 2:1–13","sequence":3,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1F1THtjtqn-tkklilxM2cSrmZk-oWWnwP-vdlPyFfv6A/edit"},{"id":"ACT-004","track":"ACT","title":"부활하신 예수를 주와 그리스도로","passage":"행 2:14–36","sequence":4,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1KC-dWVhPUWUMXn1cxQZoPJXPmii2hSG6tALG-CDqiEc/edit"},{"id":"ACT-005","track":"ACT","title":"성령으로 이루어진 공동체","passage":"행 2:37–47","sequence":5,"phase":"MAIN","available":false,"doc":""},{"id":"ACT-006","track":"ACT","title":"예수님의 이름으로 걷게 된 사람","passage":"행 3:1–16","sequence":6,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-001","track":"PSA","title":"언제까지입니까, 주님?","passage":"시 13:1–6","sequence":1,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1riRGcKji_e-XQtPyWZhz260WQv4DnUc13s8ddxiHTQo/edit"},{"id":"PSA-002","track":"PSA","title":"낙심한 영혼의 기도","passage":"시 42:1–11","sequence":2,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-003","track":"PSA","title":"하나님의 빛과 진리를 구하다","passage":"시 43:1–5","sequence":3,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-004","track":"PSA","title":"마음을 하나님께 쏟아놓다","passage":"시 62:1–8","sequence":4,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-005","track":"PSA","title":"두려움 가운데 하나님을 바라보다","passage":"시 27:1–6","sequence":5,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-006","track":"PSA","title":"주의 얼굴을 구하며 기다리다","passage":"시 27:7–14","sequence":6,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-007","track":"PSA","title":"깊은 곳에서 부르짖다","passage":"시 130:1–8","sequence":7,"phase":"MAIN","available":false,"doc":""},{"id":"EPI-001","track":"EPI","title":"하나님의 아들에 관한 복음","passage":"롬 1:1–7","sequence":1,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1zbKO59r-PRrEhgcupvkq_CLynYil-mUMPe6ZrsR_j0U/edit"},{"id":"EPI-002","track":"EPI","title":"복음을 부끄러워하지 않는 이유","passage":"롬 1:8–17","sequence":2,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1OdiCFGOii3rFX3RxA2MVdSVkjx_bjdgXE4cJdtbv73Y/edit"},{"id":"EPI-HBR-START","track":"EPI","title":"아들을 통해 말씀하신 하나님","passage":"히 1:1–4","sequence":1000,"phase":"FUTURE_BOOK","available":false,"doc":""},{"id":"OTN-001","track":"OTN","title":"내 말을 네 입에 두었다","passage":"렘 1:4–10","sequence":1,"phase":"FIRST","available":true,"doc":"https://docs.google.com/document/d/1zVPxU8xNWuCjH0e-pNHBWDlobZWWQisitX-2Wu3bsq8/edit"},{"id":"OTN-002","track":"OTN","title":"내 말을 지켜 이루시는 하나님","passage":"렘 1:11–19","sequence":2,"phase":"MAIN","available":false,"doc":""},{"id":"PSA-008","track":"PSA","title":"어린아이처럼 마음을 고요히 하다","passage":"시 131:1–3","sequence":8,"phase":"MAIN","available":false,"doc":""},{"id":"EPI-003","track":"EPI","title":"진리를 억누르는 사람","passage":"롬 1:18–32","sequence":3,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1ZhVq9L-YCYeEn-QrNSxShNTpSLcESuDyaZZCFSI6ZNU/edit"},{"id":"EPI-004","track":"EPI","title":"하나님의 의로운 심판","passage":"롬 2:1–16","sequence":4,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1CQ-LxkBvJxRFUJgpBAh_XyLGoFk5J75K4MA4X0-2BNE/edit"},{"id":"PSA-R70-001","track":"PSA","title":"여호와의 율법을 즐거워하는 사람","passage":"시 1:1–6","sequence":1,"phase":"MAIN","available":true,"doc":"https://docs.google.com/document/d/1diQaeggcTcPzdeGMxWKEi6QADH53FtvIkAwqF7KcBvE/edit"}],"entries":[{"id":"INT-001","track":"JES","title":"구유에 누이신 구주","passage":"눅 2:1–20","excerpt":"다윗의 고을에 너희를 위해 구원자가 태어나셨다.","bible":"https://www.bible.com/ko/bible/142/LUK.2.RNKSV","verses":[{"n":1,"text":"그 무렵 카이사르 아우구스투스에게서 온 세상이 등록하도록 하는 칙령이 나왔다."},{"n":2,"text":"이 첫 등록은 구레뇨가 시리아를 다스릴 때 이루어졌다."},{"n":3,"text":"그래서 모든 사람이 등록하려고 각각 자기 고을로 갔다."},{"n":4,"text":"요셉도 다윗의 집안과 가문에 속했기 때문에 갈릴리의 나사렛에서 유대에 있는 다윗의 고을 베들레헴으로 올라갔다."},{"n":5,"text":"그는 자기와 약혼한, 임신 중인 마리아와 함께 등록하려고 했다."},{"n":6,"text":"그들이 거기 머무는 동안 마리아가 아이를 낳을 날이 찼다."},{"n":7,"text":"마리아는 맏아들을 낳아 포대기로 싸서 구유에 눕혔다. 그들이 묵는 곳에는 그들을 위한 자리가 없었기 때문이다."},{"n":8,"text":"그 지역에는 목자들이 들에서 지내며 밤중에 양 떼를 지키고 있었다."},{"n":9,"text":"주님의 천사가 그들 곁에 서고 주님의 영광이 그들 주위를 비추자 그들은 크게 두려워했다."},{"n":10,"text":"천사가 그들에게 말했다. “두려워하지 마라. 보라, 내가 온 백성에게 큰 기쁨이 될 좋은 소식을 너희에게 전한다."},{"n":11,"text":"오늘 다윗의 고을에 너희를 위해 구원자가 태어나셨다. 그분은 그리스도이신 주님이다."},{"n":12,"text":"너희에게 줄 표징은 이것이다. 포대기에 싸여 구유에 누워 있는 아기를 발견할 것이다.”"},{"n":13,"text":"갑자기 그 천사와 함께 많은 하늘의 군대가 나타나 하나님을 찬양하며 말했다."},{"n":14,"text":"“지극히 높은 곳에서는 하나님께 영광, 땅에서는 하나님이 기뻐하시는 사람들 가운데 평화.”"},{"n":15,"text":"천사들이 그들을 떠나 하늘로 올라간 뒤, 목자들은 서로 말했다. “베들레헴까지 가서 주님께서 우리에게 알려 주신 이 일을 보자.”"},{"n":16,"text":"그들은 서둘러 가서 마리아와 요셉과 구유에 누워 있는 아기를 찾아냈다."},{"n":17,"text":"아기를 보고 나서 그들은 이 아기에 관해 자신들에게 들려온 말씀을 알렸다."},{"n":18,"text":"목자들이 전한 말을 들은 사람들은 모두 놀랐다."},{"n":19,"text":"그러나 마리아는 이 모든 말을 마음에 간직하고 곰곰이 되새겼다."},{"n":20,"text":"목자들은 자기들이 듣고 본 모든 일이 자신들에게 알려진 그대로였으므로 하나님께 영광을 돌리고 찬양하며 돌아갔다."}],"sections":[{"heading":"배경과 앞뒤 문맥","paragraphs":["누가복음 1장에서 천사는 마리아에게 태어날 아기가 하나님의 아들이며 다윗의 왕위를 이어받을 분이라고 알립니다(1:32–35). 2장에서는 로마 황제의 등록 명령으로 요셉과 마리아가 다윗의 고을 베들레헴에 가고, 그곳에서 예수님이 태어나십니다. 하나님의 약속이 거대한 제국의 역사와 평범한 사람들의 삶 한가운데서 이루어집니다. 다음 단락(2:21–40)에서는 시므온과 안나가 이 아기에게서 하나님이 준비하신 구원을 알아봅니다."]},{"heading":"오늘의 말씀 — 우리를 위하여 오신 구주","paragraphs":["황제 아우구스투스의 명령으로 사람들이 이동하는 동안 요셉과 마리아도 나사렛을 떠나 베들레헴으로 갑니다. 세상의 눈에는 황제의 명령이 역사를 움직이는 것처럼 보입니다. 그러나 누가는 다윗의 고을에서 태어난 한 아기에게 우리의 시선을 머물게 합니다. 하나님이 오래전 약속하신 구원자가 바로 그분이기 때문입니다. 존 파이퍼는 이 장면을 하나님의 섭리라는 관점에서 읽습니다. 인간의 큰 권력이 역사의 전부가 아니라는 것입니다. 이는 누가가 기록한 사건을 성경 전체의 하나님의 주권에 비추어 이해한 신학적 해석입니다.","그날 밤 목자들은 주님의 영광을 보고 두려워합니다. 그러나 천사는 그들에게 두려워하지 말라고 말하며 이유를 알려 줍니다. “오늘 다윗의 고을에 너희를 위해 구원자가 태어나셨다”(11절). 복음의 첫머리에는 목자들이 이루어 낸 자격이나 업적이 아니라 그들을 **위하여** 오신 구주가 계십니다. 이 아기는 죄인에게 구원을 베푸실 구원자이며, 약속된 그리스도이고, 우리의 경배를 받으실 주님입니다. 구유에 누인 연약한 아기의 모습과 그분께 주어진 위대한 이름 사이의 대조는, 하나님의 아들이 우리를 구원하시려고 참사람으로 오셨다는 성육신의 신비를 생각하게 합니다(요 1:14; 빌 2:6–8).","하늘의 군대가 부르는 찬송은 그 탄생의 의미를 선포합니다. “지극히 높은 곳에서는 하나님께 영광, 땅에서는 하나님이 기뻐하시는 사람들 가운데 평화”(14절). 파이퍼는 하나님의 영광과 우리에게 주시는 평화를 함께 붙들어야 한다고 설명합니다. 예수님은 하나님을 영화롭게 하시며 죄인을 하나님과 화목하게 하시는 분입니다. 십자가와 부활을 통해 이루실 구원을 생각하면, 천사들이 노래한 평화는 하나님과의 관계가 회복되는 복음으로 더욱 선명해집니다(롬 5:1; 엡 2:14–16). 그 평화는 오늘의 모든 문제가 사라졌다는 선언을 넘어, 구주께 속한 사람에게 주어지는 새로운 관계와 소망입니다.","목자들은 구원의 소식을 듣고 베들레헴으로 달려갑니다. 아기를 보고 말씀을 전하며 하나님을 찬양합니다. 마리아는 그 모든 말을 마음에 간직하고 되새깁니다. 구원의 소식이 먼저 들려왔고, 그 은혜가 그들의 발걸음과 마음과 입술을 움직였습니다. 믿음의 응답은 우리 힘으로 기쁨을 만들어 내는 일에서 시작하지 않습니다. 우리를 위해 오신 예수님이 누구신지 더욱 알고, 그분을 신뢰하며 하나님께 영광 돌리는 데서 자라납니다."]},{"heading":"중요한 절을 깊이 읽기","paragraphs":["7절 — 구유에 누이신 아기. 누가는 예수님이 포대기에 싸여 구유에 누이셨다고 기록합니다. 이 장면을 보며 참으로 우리 가운데 오신 하나님의 아들을 바라봅니다. 그분의 낮아지심은 훗날 자신을 내어주시는 구원의 길과 연결됩니다(고후 8:9).","11절 — 구원자·그리스도·주님. ‘너희를 위하여’라는 선포는 이 탄생이 우리를 향한 하나님의 구원 행위임을 드러냅니다. 예수님의 세 칭호는 그분의 사명과 약속된 왕의 정체성, 주 되심을 한꺼번에 보여 줍니다.","14절 — 하나님의 영광과 땅의 평화. 평화는 하나님의 호의를 입은 사람들 가운데 선포됩니다. 구원의 시작과 목적이 하나님께 있으며, 평화는 그분이 보내신 구주를 통해 우리에게 주어집니다."]},{"heading":"신앙의 선배들에게 배우기","paragraphs":["존 파이퍼는 「A Savior Is Born: Glory to God, Peace to Man」(2011)에서 누가복음 2:14의 ‘하나님의 영광’과 ‘사람에게 주시는 평화’를 그리스도 탄생의 두 중심 결과로 설명합니다. 그는 그 평화가 무엇보다 하나님과의 화목에서 시작되며, 그리스도와 분리된 단순한 마음의 안정으로 축소될 수 없다고 강조합니다. 또 「A Big God for Little People」(1980)에서는 1–5절을 하나님의 섭리라는 관점에서, 6–7절을 그리스도의 낮아지심과 십자가에 이르는 길에 비추어 읽습니다."]},{"heading":"묵상 질문","paragraphs":["1. 천사가 “너희를 위하여 구원자가 태어나셨다”고 말할 때, 그 선포는 내가 예수님을 바라보는 방식을 어떻게 바꿉니까?","2. 목자들이 기뻐하고 찬양한 출발점은 무엇이었습니까? 오늘 나는 어떤 구원의 약속을 마음에 간직하고 싶습니까?"]},{"heading":"기도","paragraphs":["주 예수님, 저를 위하여 이 땅에 오신 구주를 믿음으로 바라보게 하소서. 주님이 십자가로 이루신 하나님과의 평화를 더욱 깊이 알고, 두려움 가운데서도 주님을 신뢰하며 찬양하게 하소서. 아멘."]}],"sources":[{"author":"John Piper","title":"A Savior Is Born: Glory to God, Peace to Man","kind":"설교","url":"https://www.desiringgod.org/messages/a-savior-is-born-glory-to-god-peace-to-man"},{"author":"John Piper","title":"A Big God for Little People","kind":"설교","url":"https://www.desiringgod.org/messages/a-big-god-for-little-people"}],"preview":true},{"id":"ACT-001","track":"ACT","title":"떠나신 것이 끝이 아닙니다","passage":"행 1:1–11","excerpt":"승천하신 예수님은 성령을 통해 어떻게 계속 일하시는가?","bible":"https://www.bible.com/ko/bible/142/ACT.1.RNKSV","verses":[{"n":1,"text":"데오빌로여, 나는 첫 번째 글에서 예수님이 행하고 가르치기 시작하신 모든 일에 관해 기록했다."},{"n":2,"text":"곧 그분이 택하신 사도들에게 성령을 통하여 명령하신 뒤 하늘로 들려 올라가신 날까지의 일이다."},{"n":3,"text":"예수님은 고난을 받으신 뒤 그들에게 자신이 살아 계심을 많은 확실한 증거로 보여 주셨다. 사십 일 동안 그들에게 나타나셔서 하나님 나라에 관한 일들을 말씀하셨다."},{"n":4,"text":"그들과 함께 모여 계실 때 예수님은 그들에게 명령하셨다. “예루살렘을 떠나지 말고, 너희가 내게서 들은 아버지의 약속을 기다려라.”"},{"n":5,"text":"“요한은 물로 세례를 주었지만, 너희는 이제 며칠 지나지 않아 성령으로 세례를 받을 것이다.”"},{"n":6,"text":"그들이 함께 모였을 때 예수님께 물었다. “주님, 이때에 이스라엘에게 나라를 회복해 주시겠습니까?”"},{"n":7,"text":"예수님이 그들에게 말씀하셨다. “아버지께서 자신의 권한으로 정해 두신 때와 시기는 너희가 알 일이 아니다.”"},{"n":8,"text":"“그러나 성령이 너희 위에 임하시면 너희는 능력을 받고, 예루살렘과 온 유대와 사마리아에서, 그리고 땅끝에 이르기까지 나의 증인이 될 것이다.”"},{"n":9,"text":"이 말씀을 하신 뒤, 그들이 보는 가운데 예수님이 들어 올려지셨고 구름이 그분을 가려 더 이상 보이지 않게 되었다."},{"n":10,"text":"예수님이 올라가시는 동안 그들이 하늘을 유심히 바라보고 있는데, 보라, 흰 옷을 입은 두 사람이 그들 곁에 서 있었다."},{"n":11,"text":"그들이 말했다. “갈릴리 사람들아, 어찌하여 하늘을 바라보며 서 있느냐? 너희에게서 하늘로 올려지신 이 예수님은, 그분이 하늘로 가시는 것을 너희가 본 그대로 다시 오실 것이다.”"}],"sections":[{"heading":"오늘의 질문","paragraphs":["예수님은 하늘로 올라가셨는데, 사도행전은 왜 예수님이 계속 일하시는 이야기일까요?"]},{"heading":"성경 본문 안내","paragraphs":["(공인 번역본의 복제가 아닌 프로젝트 자체 번역 검토본)","성경 앱 전체 읽기: https://www.bible.com/ko/bible/142/ACT.1.RNKSV"]},{"heading":"본문을 깊이 읽기 | 사라지지 않은 주님, 새롭게 시작된 증언","paragraphs":["누가복음의 마지막 장에서 제자들은 부활하신 예수님이 성경을 풀어 주시는 말씀을 듣고, 그분의 승천을 목격합니다. 사도행전은 같은 데오빌로에게 그 뒤의 이야기를 이어 씁니다. 누가는 예수님의 지상 사역을 그분이 “행하고 가르치기 시작하신 일”이라고 부릅니다(1절). 이상한 표현입니다. 예수님의 지상 사역이 끝났다면 왜 ‘시작’이라고 합니까? 그분의 십자가와 부활로 이루어진 구원은 결코 다시 반복될 일이 아닙니다. 그러나 높임받으신 예수님이 하나님 나라를 확장하시며 자신의 백성 가운데 일하시는 일은 여기서 새로운 국면을 맞습니다.","첫째, 부활하신 주님의 다스림은 사도들의 확실한 증언 위에 세워집니다(1–3절). 누가는 예수님의 죽음을 믿는 것이 아니라, 고난 후 실제로 살아 계신 주님이 자신을 보여 주신 사건을 말합니다. 사십 일 동안 나타나신 일과 하나님 나라에 관한 가르침은 교회의 증언이 막연한 종교적 열정이 아니라 부활하신 분의 행동과 말씀에 뿌리내렸음을 보여 줍니다. 사도행전의 주인공을 베드로나 바울만으로 볼 수 없는 이유입니다. 그들의 입과 발을 통해 선포되고 확장되는 것은 높임받으신 예수님의 나라입니다.","둘째, 예수님은 제자들의 관심을 알 수 없는 시간표에서 명령하신 사명으로 옮기십니다(4–8절). 제자들은 이스라엘의 회복 시기를 묻습니다. 예수님은 그 질문을 비웃지 않으시지만, 때와 시기는 아버지의 권한에 있다고 가르치십니다. 대신 아버지의 약속인 성령을 기다리게 하시고, 그 영이 임하실 때 “나의 증인”이 될 것이라고 말씀하십니다. 이 능력은 자기 인생을 통제하는 기술이 아닙니다. 예수님에 대해 증언하도록 주어지는 선물입니다. 그리고 예루살렘·유대·사마리아·땅끝이라는 공간의 확장은, 하나님이 예수님 안에서 이루시는 구원이 경계를 넘어 사람들에게 다가갈 것을 예고합니다.","셋째, 승천은 예수님의 부재가 아니라 왕 되심을 바라보게 합니다(9–11절). 구름에 가려진 뒤 제자들은 하늘만 바라보고 있습니다. 두 사람이 전하는 말에는 이 예수님이 다시 오시리라는 약속이 담깁니다. 교회는 예수님이 떠나셔서 모든 책임을 인간에게 떠넘긴 조직이 아닙니다. 이미 이루신 구원을 바탕으로 지금도 역사하시는 주님의 증인이며, 다시 오실 주님을 기다리는 공동체입니다. 기다림과 증언은 서로 반대가 아닙니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 시간을 모두 알려 주시지 않지만, 자기 아들의 부활을 증언하게 하시는 일을 위해 성령을 약속하십니다. 예수님의 백성은 미래를 정확히 맞히는 사람들이 아니라 지금 살아 계신 그리스도를 신뢰하고 그분에 대해 진실하게 말하는 사람들입니다. 교회가 무엇을 하든 가장 먼저 묻게 되는 질문도 같습니다. 이것은 우리의 계획을 위한 일입니까, 아니면 부활하신 예수님에 대한 증언입니까?"]},{"heading":"묵상 질문","paragraphs":["1. 나는 하나님이 알려 주지 않으신 시기와 결과를 알고 싶은 마음 때문에 오늘 분명하게 주신 말씀을 미루고 있지는 않습니까?","2. 사도행전 1장이 묘사하는 예수님은 나에게 이미 떠나신 스승입니까, 아니면 지금도 다스리시는 살아 계신 주님입니까?"]},{"heading":"기도","paragraphs":["죽음을 이기시고 높임받으신 주 예수님, 제가 교회의 능력을 사람의 성취에서 찾지 않고 주님의 부활과 약속에서 찾게 하소서. 알 수 없는 시간을 움켜쥐려는 마음을 내려놓고, 주님의 성령을 의지하여 맡겨 주신 자리에서 참된 증인으로 살게 하소서. 아멘."]},{"heading":"깊이 읽기 | 설교와 주석의 논증","paragraphs":["존 파이퍼 — “What Jesus Did After the Beginning” (1990)","파이퍼는 1절의 한 단어인 ‘시작하셨다’에 설교의 핵심을 둡니다. 누가복음은 예수님이 무엇을 행하고 가르치셨는지 기록했습니다. 그런데 누가가 사도행전을 쓰면서 그것을 ‘시작’이라고 부르는 것은 예수님의 행하심과 가르치심이 제자들에게 이어지는 사역을 통해 계속되기 때문이라는 것입니다. 파이퍼는 이 사실을 이해하기 위해 로마서 15:18–19을 연결합니다. 바울조차 자기 사역의 결과를 자신이 한 일로 자랑하지 않고 ‘그리스도가 나를 통해 이루신 것’을 말합니다. 성령을 통한 사도의 말과 행동을 통해 일하시는 분은 살아 계신 그리스도입니다.","파이퍼는 그렇다고 십자가의 단번에 이루어진 구원이 미완성이라는 뜻은 아니라는 점을 분명히 합니다. 그리스도의 희생은 완결되었고, 그 구원의 효력과 복음의 선포가 역사 속으로 전해지고 있습니다. 사도들에게는 이 사역을 위한 세 가지가 주어졌다고 설명합니다. 첫째, 예수님이 성령을 통해 명하신 사명입니다. 둘째, 부활이 실제라는 확실한 증거입니다. 셋째, 하나님 나라에 대한 주님의 가르침입니다. 그리고 이 세 가지를 가능하게 하는 성령의 약속이 이어집니다. 이 설교를 따라 읽으면 사도행전은 사람의 종교적 결심을 과장하는 책이 아니라 그리스도가 행하시고 가르치시는 일을 보게 하는 책이 됩니다.","존 파이퍼 — “You Shall Receive Power...For Mission” (1988)","이 설교의 중심은 성령의 능력과 선교의 목적을 분리할 수 없다는 데 있습니다. 제자들은 예수님의 명령을 듣고 곧장 인간의 열심으로 세계에 뛰어들지 않습니다. 예루살렘에 남아 아버지의 약속을 기다려야 합니다. 파이퍼는 누가복음 24장의 약속과 사도행전 1:8을 함께 읽으며, 교회가 받은 능력은 성령을 통해 그리스도를 증언하기 위한 것임을 강조합니다.","특히 성령의 임재가 주는 능력은 개인의 성공이나 영향력 확장을 보증하는 언어가 아니라, 복음의 진리가 사람과 장소의 경계를 넘어 퍼지도록 하는 하나님의 주도권을 뜻합니다. 따라서 성령에 의존한다는 것은 아무 행동도 하지 않는다는 의미가 아닙니다. 오히려 사도들은 그 능력에 의지하여 자신이 본 예수님의 죽음과 부활을 증언하게 됩니다. 파이퍼가 본문의 약속을 현대 교회의 세계 선교에 연결하는 이유가 여기에 있습니다.","앨런 J. 톰프슨 — “Acts”, The Gospel Coalition Bible Commentary","톰프슨은 사도행전 전체의 중심을 ‘예수님이 계속 다스리시는 나라’에서 찾습니다. 누가는 예수님의 승천을 누가복음과 사도행전을 잇는 경첩처럼 배치합니다. 지상에서의 사역은 끝났지만 그분의 하늘 사역은 시작되었고, 1장의 “택하신 사도들”과 “하나님 나라”라는 표현은 28장 마지막의 복음 선포까지 반복되는 주제를 만듭니다.","톰프슨은 제자들의 이스라엘 회복 질문(6절)을 완전히 잘못된 것으로 잘라내지 않습니다. 하나님 나라에 대한 구약의 약속과 이스라엘, 이방인의 포함이라는 문제는 사도행전 전체에서 전개됩니다. 예수님의 답변은 그 성취의 시각이 아버지께 있음을 밝히면서, 이사야가 말한 성령과 증인의 약속을 예루살렘에서 땅끝에 이르는 복음의 길로 연결합니다. 그렇게 성령의 파송, 교회의 확장, 이방인의 포함은 모두 높은 곳에서 통치하시는 예수님의 일로 읽힙니다."]},{"heading":"원어와 문맥 보충","paragraphs":["1절 ‘시작하다’(ἤρξατο)의 표현과 ‘행하고 가르치다’의 결합이 누가복음과 사도행전 사이를 잇습니다.","6–8절 ‘때와 시기’의 한계와 ‘증인의 능력’은 서로 대조되지만, 하나님 나라의 소망 자체를 포기하라는 명령은 아닙니다.","9–11절 승천과 재림 약속은 실제 제자들의 증언과 그 뒤의 성령 강림을 연결하는 시간적·신학적 전환점입니다."]}],"sources":[{"author":"John Piper","title":"what jesus did after the beginning","kind":"설교","url":"https://www.desiringgod.org/messages/what-jesus-did-after-the-beginning"},{"author":"John Piper","title":"you shall receive power for mission","kind":"설교","url":"https://www.desiringgod.org/messages/you-shall-receive-power-for-mission"},{"author":"The Gospel Coalition","title":"acts","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/acts/"}],"preview":false,"unit_type":"DEEP"},{"id":"EPI-001","track":"EPI","title":"하나님의 아들에 관한 복음","passage":"롬 1:1–7","excerpt":"복음의 중심이 그리스도인 까닭은 무엇인가?","bible":"https://www.bible.com/ko/bible/142/ROM.1.RNKSV","verses":[{"n":1,"text":"그리스도 예수의 종 바울, 부르심을 받은 사도이며 하나님의 복음을 위하여 따로 세워진 사람으로서,"},{"n":2,"text":"이 복음은 하나님께서 자기 예언자들을 통하여 거룩한 성경에 미리 약속하신 것이며,"},{"n":3,"text":"그의 아들에 관한 것입니다. 그 아들은 육신으로는 다윗의 후손에게서 나셨고,"},{"n":4,"text":"거룩함의 영을 따라서는 죽은 이들 가운데서 부활하심으로 능력 가운데 하나님의 아들로 선포되셨습니다. 곧 우리의 주 예수 그리스도이십니다."},{"n":5,"text":"우리는 그분을 통하여 은혜와 사도의 직분을 받아 그분의 이름을 위하여 모든 민족 가운데 믿음의 순종을 이루도록 부름받았습니다."},{"n":6,"text":"여러분도 그 민족들 가운데 있으며 예수 그리스도의 부르심을 받은 사람들입니다."},{"n":7,"text":"로마에 있는, 하나님의 사랑을 받고 성도로 부르심 받은 모든 이에게, 우리 아버지 하나님과 주 예수 그리스도에게서 은혜와 평화가 있기를 빕니다."}],"sections":[{"heading":"오늘의 질문","paragraphs":["바울은 긴 로마서의 첫머리에서 왜 자신이나 로마 교회보다 하나님의 아들 예수 그리스도를 먼저 소개할까요?"]},{"heading":"성경 본문 안내","paragraphs":["(기존 프로젝트에서 직접 번역한 검토본)","전체 본문 비교 읽기: https://www.bible.com/ko/bible/142/ROM.1.RNKSV"]},{"heading":"본문을 깊이 읽기 | 하나님께서 시작하시고 그 아들 안에서 완성하신 복음","paragraphs":["바울은 아직 직접 방문하지 못한 로마 교회에 편지를 보냅니다. 이 편지는 그가 전하는 복음의 내용과 그 결과로 빚어지는 새로운 삶을 긴 논증으로 펼칠 것입니다. 그런데 바울은 교회의 논쟁이나 실천 문제를 논하기 전에 자신을 그리스도 예수의 ‘종’으로, 하나님께 부름받은 ‘사도’로 소개합니다. 그는 복음을 발명한 사람이 아닙니다. 예수 그리스도에게 속하여 하나님이 약속하신 소식을 전하는 사람입니다.","첫째, 복음은 인간이 만든 새로운 사상이 아니라 하나님이 미리 약속하신 말씀입니다(1–2절). ‘복음’은 위로가 되는 이야기 하나가 아닙니다. 하나님이 주체이시며, 그 약속은 예언자들을 통해 주신 성경 안에 뿌리를 둡니다. 따라서 로마서는 구약과 분리된 새로운 종교를 설명하려는 글이 아닙니다. 바울이 전하는 예수님은 아브라함과 다윗에게 이어진 하나님의 약속을 성취하시는 분입니다.","둘째, 복음은 무엇을 해야 구원을 얻는가에 대한 지침보다 먼저 누구에게 구원이 있는가를 밝힙니다(3–4절). 복음의 내용은 ‘그 아들에 관한 것’입니다. 예수님은 다윗의 후손으로 역사 가운데 오신 참사람이시며, 죽은 이들 가운데서 부활하심으로 능력 가운데 하나님의 아들로 선포되신 분입니다. 바울은 원래 단순한 사람이었던 예수님이 부활 후 신적인 존재로 바뀌었다고 가르치지 않습니다. 그는 성육신과 부활을 함께 언급함으로써, 하나님이 약속하신 왕이 죽음의 권세를 이기고 주님으로 다스리신다는 사실을 선포합니다. 이 복음이 바울의 사역을 설명하고 로마 교회의 존재를 설명합니다.","셋째, 은혜는 믿음의 순종을 낳습니다(5–7절). 바울은 그리스도를 통하여 ‘은혜와 사도의 직분’을 받았습니다. 사도라는 직분은 개인의 성취가 아니라 그분이 맡기신 사명이었습니다. 그의 목적은 모든 민족 가운데 ‘믿음의 순종’을 일으키고 그리스도의 이름을 드러내는 것입니다. 은혜와 순종은 거래 관계가 아닙니다. 순종하여 은혜를 얻는 것이 아니라 먼저 은혜로 부르심받은 사람이 믿음을 통해 그분께 응답합니다. 그래서 바울은 로마 성도들에게도 ‘하나님의 사랑을 받는 사람’, ‘성도로 부름받은 사람’이라는 이름을 줍니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["복음의 첫머리에는 인간의 종교심보다 하나님의 신실하심이 있습니다. 하나님은 자기 약속을 잊지 않으셨고, 그 아들을 보내셨으며, 죽음에서 일으키셨습니다. 그리고 은혜를 받은 사람이 그 이름을 믿고 순종하는 삶으로 들어가도록 부르십니다. 하나님이 어떤 분인지 알아갈수록, 나의 믿음은 내가 얼마나 훌륭한지를 증명하려는 수고에서 예수 그리스도께 의지하는 응답으로 옮겨갑니다."]},{"heading":"묵상 질문","paragraphs":["1. 복음을 말할 때 나는 먼저 내가 얻을 결과를 설명합니까, 아니면 하나님이 보내신 예수 그리스도가 누구신지를 말합니까?","2. 오늘 내게 어려운 순종이 있다면, 그것을 은혜를 얻는 조건이 아니라 이미 받은 은혜에 대한 믿음의 응답으로 볼 수 있을까요?"]},{"heading":"기도","paragraphs":["하나님 아버지, 오래전부터 약속하시고 아들 예수 그리스도 안에서 성취하신 복음을 더 깊이 알게 하소서. 저의 의로움이 아니라 주님의 은혜에 기대게 하시고, 믿음으로 받은 사랑이 순종의 열매를 맺게 하소서. 예수님의 이름으로 기도합니다. 아멘."]},{"heading":"깊이 읽기 | 복음주의 설교와 주석의 논증","paragraphs":["존 파이퍼 — “God’s Good News Concerning His Son” (1998)","파이퍼는 먼저 바울이 ‘그리스도의 종’이면서 ‘사도’인 관계를 살핍니다. 바울은 스스로 복음을 소유한 사람처럼 자신을 소개하지 않습니다. 그리스도께 속한 사람으로 부름받아 그분이 주신 권위와 능력으로 섬깁니다. 이어 그는 ‘하나님의 복음’이라는 표현을 둘로 나누어 질문합니다. 복음의 근원은 누구이며, 복음의 내용은 누구인가? 근원은 하나님입니다. 그분이 구약의 예언자들을 통해 미리 약속하셨고, 그 아들을 세상에 보내셨습니다. 복음은 그 아들에 관한 소식입니다. 이 사실을 놓치면 구원의 은혜를 그리스도에게서 떨어져 나온 추상적인 혜택처럼 오해하기 쉽습니다.","파이퍼는 그 아들이 역사 가운데 다윗의 후손으로 오셨다는 사실을 구약의 왕권 약속과 연결합니다. 이 왕은 단지 한 시대의 정치적 인물이 아니라 하나님의 약속을 성취하시는 메시야입니다. 그는 이미 성육신 이전부터 하나님의 아들이셨고, 사람으로 오셔서 죽으시고 부활하심으로써 ‘능력 가운데 하나님의 아들’이심을 나타내셨습니다. 따라서 부활은 예수님이 처음으로 하나님의 아들이 된 순간이 아니라 그분의 승리와 높임을 선포하는 전환점입니다. 파이퍼가 본문을 붙들고 싶은 이유는, 독자가 단지 기독교의 혜택이 아니라 살아 계신 구주 자신을 바라보게 하기 위해서입니다.","존 파이퍼 — “By His Grace, for His Name, Through the Obedience of Faith” (1998)","이 설교는 5절의 세 표현을 중심으로 전개됩니다. 첫째, ‘은혜와 사도직’은 바울의 사역이 주님의 자유로운 선물이라는 뜻입니다. 바울이 먼저 자격을 획득했기 때문에 사도가 된 것이 아닙니다. 그리스도가 은혜를 베푸셨고 그 은혜로 사도의 임무를 감당하도록 능력을 주셨습니다. 파이퍼는 로마서 12장, 15장과 연결하여 은혜가 죄인을 용서하는 호의일 뿐 아니라 주님께 순종하고 섬기도록 붙드는 실제적인 능력이기도 하다고 설명합니다.","둘째, ‘믿음의 순종’은 믿음과 순종을 분리할 수 없음을 보여 줍니다. 파이퍼는 이 표현이 ‘믿음 자체로 이루어지는 순종’인지 ‘믿음에서 비롯되는 순종’인지를 검토한 뒤, 바울의 더 넓은 논증을 따라 참된 순종이 믿음에서 흘러나온다는 점을 강조합니다. 믿음은 자신 안에 충분한 힘이 있다고 주장하는 일이 아니라, 하나님의 은혜를 받아들이고 그 은혜에 의지하는 행동입니다. 셋째, 이 모든 목적은 ‘그의 이름을 위하여’라는 마지막 구절에 달려 있습니다. 은혜의 근원이 하나님이시므로 순종의 공로도 인간에게 돌아가지 않습니다. 그리스도의 이름이 알려지고 찬양받는 것이 바울의 사역과 복음의 목적이라는 것입니다. 그래서 은혜는 순종의 대가가 아니라 순종을 가능하게 하는 선물입니다.","도니 레이 매시스 — “Romans”, The Gospel Coalition Bible Commentary","매시스는 로마서 인사말이 다른 바울 서신보다 유난히 길다는 데 주목합니다. 아직 직접 방문하지 않은 로마 교회 앞에서 바울은 자신이 전하는 복음과 사도의 권위가 무엇인지 미리 밝힙니다. 그는 자신의 사역을 구약의 약속과 연결하고, 예수님의 다윗 왕가 계보와 부활로 나타난 능력을 함께 제시합니다. 인사말의 끝에 나타나는 ‘은혜와 평화’는 장식이 아니라, 하나님의 사랑을 받는 백성의 존재를 설명하는 복음의 언어입니다.","매시스의 해설을 따라가면 1:1–7은 단순히 앞으로 펼쳐질 논증의 예고편이 아닙니다. 이미 복음의 주제와 근거가 압축되어 있습니다. 하나님이 먼저 약속하셨고, 그 약속이 예수 그리스도 안에 구체적으로 성취되었으며, 은혜를 받은 자들이 모든 민족 가운데 그 이름을 위해 살아가도록 부름받았습니다. 다음 회차인 1:8–17의 ‘복음을 부끄러워하지 않는다’는 선언은 바로 이 인사말 위에서 이해되어야 합니다.","원어와 해석 보충","1절 ‘복음을 위하여 따로 세워진’(ἀφωρισμένος)은 바울의 사명에 대한 표현입니다.","4절 ‘선포되었다/지정되었다’(ὁρισθέντος)와 ‘능력 가운데’(ἐν δυνάμει)의 관계에는 번역상의 논의가 있습니다. 부활을 통해 영원한 하나님의 아들 지위가 비로소 생겼다는 식의 이해는 본문의 신학적 흐름에 맞지 않습니다.","5절 ‘믿음의 순종’(ὑπακοὴν πίστεως)은 믿음과 순종의 연결을 압축합니다. 그 관계를 뒤이어 로마서 4장과 6장, 12장에서 다시 살핍니다."]}],"sources":[{"author":"John Piper","title":"gods good news concerning his son","kind":"설교","url":"https://www.desiringgod.org/messages/gods-good-news-concerning-his-son"},{"author":"John Piper","title":"by his grace for his name through the obedience of faith","kind":"설교","url":"https://www.desiringgod.org/messages/by-his-grace-for-his-name-through-the-obedience-of-faith"},{"author":"The Gospel Coalition","title":"romans","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/romans/"}],"preview":false,"unit_type":"DEEP"},{"id":"PSA-001","track":"PSA","title":"언제까지입니까, 주님?","passage":"시 13:1–6","excerpt":"언제까지입니까, 주님? 주님의 한결같은 사랑을 신뢰합니다.","bible":"https://www.bible.com/ko/bible/142/PSA.13.RNKSV","verses":[{"n":1,"text":"여호와여, 언제까지 저를 잊으시겠습니까? 영원히 그러시겠습니까? 언제까지 주님의 얼굴을 저에게서 감추시겠습니까?"},{"n":2,"text":"언제까지 제 마음속에서 스스로 궁리하고, 온종일 마음에 슬픔을 품어야 합니까? 언제까지 제 원수가 저를 이기며 높아지겠습니까?"},{"n":3,"text":"저를 돌아보시고 대답하소서, 여호와 나의 하나님. 제 눈을 밝히소서. 그렇지 않으면 제가 죽음의 잠에 빠질까 두렵습니다."},{"n":4,"text":"제 원수가 “내가 그를 이겼다”라고 말하지 못하게 하소서. 제가 흔들릴 때 제 대적들이 기뻐하지 못하게 하소서."},{"n":5,"text":"그러나 저는 주님의 한결같은 사랑을 신뢰했습니다. 제 마음은 주님의 구원을 기뻐할 것입니다."},{"n":6,"text":"여호와께 노래하겠습니다. 주님께서 제게 선하게 베푸셨기 때문입니다."}],"sections":[{"heading":"배경과 앞뒤 맥락","paragraphs":["시편 13편은 다윗의 시라는 표제를 가진 짧은 탄식시입니다. 그러나 어떤 특정한 사건에서 지어졌는지는 본문이 알려 주지 않습니다. 시인은 하나님께 버림받은 것처럼 느껴지는 고통을 토로하고(1–2절), 응답을 구한 뒤(3–4절), 하나님의 사랑을 신뢰하며 찬양합니다(5–6절). 시편 12편과 14편 사이에 있지만, 이 시를 특정한 역사적 사건의 연속 기록으로 읽을 근거는 없습니다."]},{"heading":"시편 기자의 기도를 따라가기","paragraphs":["“언제까지입니까?” 네 번 반복되는 물음은 시간이 더디게 흐르는 사람의 아픔을 그대로 담습니다. 시인은 하나님이 멀게 느껴지는 고통과 마음의 근심을 하나님께 직접 아룁니다. 주님께 부르짖는 일이 이미 하나님을 향한 믿음의 행동입니다.","기도는 '돌아보소서, 대답하소서, 내 눈을 밝히소서'라는 간구를 지나 주님의 한결같은 사랑을 신뢰하는 고백에 이릅니다. 상황이 완전히 달라졌다고 기록되지는 않습니다. 존 블룸은 시편 13편이 기다림의 괴로움을 하나님 앞에 말하도록 주어진 성경의 기도라고 설명합니다. 하나님이 자신의 백성을 버리지 않으신다는 언약의 사랑이 신뢰의 근거입니다."]},{"heading":"중요한 절","paragraphs":["1절 — “언제까지.” 반복되는 물음은 시인의 절박함을 보여 줍니다. 하나님이 실제로 그를 잊으셨다는 교리적 선언이 아니라, 그렇게 느껴지는 고통을 하나님께 호소하는 기도의 언어입니다.","3절 — “제 눈을 밝히소서.” 눈에 다시 빛을 주시라는 요청은 시들어 가는 자신의 생명을 회복해 달라는 절박한 기도입니다. 이어지는 ‘죽음의 잠’과 연결해 읽어야 합니다.","5절 — “한결같은 사랑.” 히브리어 헤세드(חֶסֶד)는 하나님이 베푸시는 신실하고 변함없는 사랑을 가리킵니다. 시인은 그 사랑을 근거로 신뢰를 고백합니다. 그 고백이 모든 문제가 이미 해결되었다는 뜻은 아닙니다."]},{"heading":"신앙의 선배들에게 배우기","paragraphs":["존 블룸은 How Long, O Lord?라는 글에서 시편 13편처럼 고통과 혼란을 정직하게 드러내는 노래가 성경에 포함되어 있다는 사실에 주목합니다. 그는 신자가 하나님의 응답이 늦다고 느낄 때 그 시간을 힘겨워하는 마음 자체를 하나님께 아뢸 수 있다고 설명합니다. 글의 아브라함과 사라의 자녀 약속을 모든 가정에 같은 방식으로 성취될 보편적 약속으로 적용하지는 않습니다."]},{"heading":"묵상 질문","paragraphs":["1. 지금 하나님께 가장 솔직하게 드리고 싶은 “언제까지입니까?”라는 질문은 무엇입니까?","2. 아직 해결되지 않은 문제 앞에서, 나는 하나님의 한결같은 사랑을 어떻게 기억할 수 있겠습니까?"]},{"heading":"시편으로 직접 기도하기","paragraphs":["“언제까지입니까?”라는 말을 넣어 지금의 마음을 하나님께 한두 문장으로 아뢰어 보십시오. 설명할 말이 떠오르지 않는다면 3절을 천천히 다시 읽어도 좋습니다. 그리고 1–2분 동안 조용히 머무르십시오. 억지로 감정을 바꾸거나 답을 만들어 낼 필요는 없습니다."]},{"heading":"짧은 기도","paragraphs":["여호와 나의 하나님, 언제 끝날지 모르는 기다림 속에서 마음이 무겁습니다. 저를 돌아보시고 응답하소서. 상황이 아직 바뀌지 않았더라도 주님의 한결같은 사랑을 놓치지 않게 하소서. 아멘.","히브리어 원문 대조: https://www.blueletterbible.org/sample/wlc/psa/13/1/"]}],"sources":[{"author":"Jon Bloom","title":"How Long, O Lord?","kind":"묵상 글","url":"https://www.desiringgod.org/articles/how-long-o-lord"}],"preview":true},{"id":"OTN-001","track":"OTN","title":"내 말을 네 입에 두었다","passage":"렘 1:4–10","excerpt":"내 말을 네 입에 두었다.","bible":"https://www.bible.com/ko/bible/142/JER.1.4-10.RNKSV","verses":[{"n":4,"text":"여호와의 말씀이 내게 임했다."},{"n":5,"text":"“내가 너를 모태에서 빚기 전에 너를 알았고, 네가 태에서 나오기 전에 너를 거룩하게 구별했다. 내가 너를 여러 민족을 향한 예언자로 세웠다.”"},{"n":6,"text":"내가 말했다. “아, 주 여호와여! 저는 말할 줄 모릅니다. 아직 젊은 사람이기 때문입니다.”"},{"n":7,"text":"그러나 여호와께서 내게 말씀하셨다. “‘저는 젊습니다’라고 말하지 마라. 내가 너를 보내는 모든 사람에게 가고, 내가 네게 명하는 모든 말을 전하여라."},{"n":8,"text":"그들 때문에 두려워하지 마라. 내가 너와 함께 있어 너를 구해 낼 것이다. 여호와의 말이다.”"},{"n":9,"text":"여호와께서 손을 내밀어 내 입에 대시고 말씀하셨다. “보라, 내가 내 말을 네 입에 두었다."},{"n":10,"text":"보라, 오늘 내가 너를 민족들과 왕국들 위에 세웠다. 뽑고 허물며 멸하고 무너뜨리며 세우고 심게 하려는 것이다.”"}],"sections":[{"heading":"배경과 문맥","paragraphs":["예레미야서는 유다 왕국 말기, 여호와께서 예언자를 통하여 전하신 말씀으로 시작합니다(1:1–3). 예레미야는 다가올 심판을 전하면서도 회복과 새 언약을 선포하게 됩니다. 이 부르심의 장면(1:4–10)에서는 예언자의 능력보다 그를 부르시고 말씀을 주시는 하나님이 중심입니다. 이어 1:11–19에서 두 환상과 함께 사명의 어려움과 하나님의 보호 약속이 구체화됩니다."]},{"heading":"오늘의 말씀 — 부르시고 말씀하시는 하나님","paragraphs":["하나님은 예레미야가 태어나기 전부터 그를 아시고 예언자로 구별하셨다고 말씀하십니다. 이 말씀은 먼저 예레미야에게 주어진 특별한 예언자 소명입니다. 하나님은 그를 뽑고 허물며 세우고 심을 말씀의 사역자로 세우십니다. 하나님의 말씀은 죄를 무너뜨리는 심판뿐 아니라 장차 새롭게 세우실 회복까지 전합니다.","예레미야는 자신이 아직 젊고 말을 잘하지 못한다고 아룁니다. 그러나 하나님은 예레미야의 타고난 설득력을 보증으로 내세우지 않으십니다. “내가 너와 함께 있다”라고 말씀하시며 친히 그 입에 말씀을 두십니다. 예언자의 권위는 자신의 확신에서 나오는 것이 아니라 그를 보내시는 하나님에게서 옵니다.","우리 모두가 예레미야와 동일한 예언자 임명을 받았다고 말할 수는 없습니다. 그럼에도 이 말씀은 하나님의 주권과 그 말씀의 능력, 자기 백성을 다루시는 하나님의 신실하심을 드러냅니다. 예레미야가 전할 심판과 회복의 긴 이야기는 결국 죄를 해결하시고 새 언약을 이루실 하나님의 약속(렘 31:31–34)을 향합니다."]},{"heading":"중요한 절","paragraphs":["5절 — ‘알았다’, ‘거룩하게 구별했다’, ‘세웠다’는 표현은 예레미야의 예언자 사명을 위해 하나님이 주도적으로 행하신 일을 나타냅니다. 모든 사람에게 예언자가 되리라는 동일한 약속으로 곧바로 확대하지 않습니다.","9–10절 — 하나님이 말씀을 예레미야의 입에 두십니다. 민족들을 뽑고 세우는 일은 예언자 개인의 힘이 아니라 그를 통해 선포되는 하나님의 말씀의 역사입니다."]},{"heading":"신앙의 선배들에게 배우기","paragraphs":["매슈 H. 패턴의 《Jeremiah》 주석(The Gospel Coalition)은 이 단락을 예레미야의 특별한 예언자 임명으로 다루고, 하나님이 그의 나이와 말의 한계를 아시면서도 명령과 임재의 약속으로 보내심을 설명합니다. R. C. 스프로울의 《Jeremiah (Part 1)》도 예레미야가 원하지 않았던 사명을 왜 감당하게 되었는지를 다룹니다. 스프로울 자료는 공식 소개문을 확인했으며 유료 전체 강의를 듣거나 내용을 문장별로 검증한 것으로 간주하지 않습니다."]},{"heading":"묵상 질문","paragraphs":["1. 예레미야에게 임한 말씀에서 하나님이 어떤 분인지 무엇을 새롭게 봅니까?","2. 하나님의 말씀을 들을 때 내 능력에 집중하는 것과 말씀하시는 주님께 귀 기울이는 것의 차이는 무엇입니까?"]},{"heading":"기도","paragraphs":["살아 계신 하나님, 말씀하시며 약속을 이루시는 주님을 경외하게 하소서. 내 확신보다 주님의 말씀을 붙들고, 진실하게 듣고 순종하게 하소서. 아멘."]}],"sources":[{"author":"Matthew H. Patton","title":"Jeremiah","kind":"복음주의 주석","url":"https://www.thegospelcoalition.org/commentary/jeremiah/"},{"author":"R. C. Sproul","title":"Jeremiah (Part 1)","kind":"강의 소개만 확인","url":"https://learn.ligonier.org/series/great-men-to-live-by/jeremiah-part"}],"preview":true},{"id":"JES-PILOT-LK05","track":"JES","title":"예수님은 왜 죄인에게 떠나지 않으셨는가?","passage":"눅 5:1–11","excerpt":"두려워하지 말라. 이제부터 너는 사람들을 살아 있는 채로 붙잡게 될 것이다.","bible":"https://www.bible.com/ko/bible/142/LUK.5.RNKSV","verses":[{"n":1,"text":"사람들이 예수님께 몰려들어 하나님의 말씀을 듣고 있을 때, 예수님은 게네사렛 호숫가에 서 계셨다."},{"n":2,"text":"그분은 호숫가에 배 두 척이 있는 것을 보셨다. 어부들은 배에서 나와 그물을 씻고 있었다."},{"n":3,"text":"예수님은 그 배 가운데 시몬의 배에 오르셔서 육지에서 조금 떨어지게 해 달라고 청하셨다. 그리고 앉으셔서 배에서 무리를 가르치셨다."},{"n":4,"text":"말씀을 마치시고 시몬에게 말씀하셨다. “깊은 곳으로 나아가라. 그리고 너희는 그물을 내려 고기를 잡아라.”"},{"n":5,"text":"시몬이 대답했다. “선생님, 저희가 온밤을 애썼지만 아무것도 잡지 못했습니다. 그러나 선생님의 말씀을 따라 제가 그물을 내리겠습니다.”"},{"n":6,"text":"그들이 그렇게 하자 엄청나게 많은 물고기를 둘러잡았고, 그들의 그물이 찢어지기 시작했다."},{"n":7,"text":"그래서 그들은 다른 배에 있는 동료들에게 손짓하여 와서 도와 달라고 했다. 그들이 와서 두 배를 가득 채우니 배들이 가라앉을 지경이 되었다."},{"n":8,"text":"시몬 베드로가 이를 보고 예수님의 무릎 앞에 엎드려 말했다. “주님, 저에게서 떠나 주십시오. 저는 죄인입니다.”"},{"n":9,"text":"그와 함께 있던 모든 사람이 그들이 잡은 물고기 때문에 놀라움에 사로잡혔기 때문이다."},{"n":10,"text":"시몬의 동료인 세베대의 아들 야고보와 요한도 마찬가지였다. 예수님은 시몬에게 말씀하셨다. “두려워하지 마라. 이제부터 너는 사람들을 살아 있는 채로 붙잡는 사람이 될 것이다.”"},{"n":11,"text":"그들은 배들을 육지로 끌어올리고 모든 것을 남겨 둔 채 예수님을 따랐다."}],"sections":[{"heading":"오늘의 질문","paragraphs":["자신을 죄인이라 고백한 시몬에게 예수님은 왜 떠나지 않으시고, 도리어 새로운 사명을 맡기셨을까요?"]},{"heading":"본문을 깊이 읽기 · 세 가지 변화","paragraphs":["누가복음 4장에서 예수님은 하나님 나라의 복음을 전파하는 일이 자신의 보내심의 목적이라고 말씀하셨습니다(4:43). 이미 시몬의 장모를 고치신 일도 있었습니다(4:38–39). 그러므로 이 장면은 시몬이 예수님에 관해 아무것도 모르던 첫 만남이라기보다, 예수님의 말씀과 권위가 시몬 자신에게 직접 다가오는 순간입니다. 누가는 처음에 ‘하나님의 말씀을 듣는 무리’를, 마지막에 ‘모든 것을 버리고 따르는 제자들’을 놓습니다. 그 사이에 일어난 것은 단순한 대박 어획이 아닙니다.","첫째, 예수님의 말씀이 시몬의 경험을 넘어섭니다(4–7절). 시몬은 어부였고, 밤새도록 일한 결과가 없었다는 사실을 알고 있었습니다. 그럼에도 그는 예수님의 말씀을 근거로 그물을 내립니다. 이 믿음은 자기 확신이나 성공을 예상하는 낙관이 아니라, 자기 판단보다 예수님의 말씀을 따르는 구체적인 행동으로 나타납니다. 그런데 이 사건에서 고기가 많이 잡혔다는 이유로 ‘말씀대로 하면 내 일도 반드시 크게 성공한다’는 공식을 만들어서는 안 됩니다. 누가는 그 많은 물고기가 시몬의 사업을 일으킨 이야기가 아니라 그를 부르시는 예수님의 권위를 드러낸 이야기로 기록합니다.","둘째, 놀라운 선물은 시몬을 자기 죄 앞에 세웁니다(8–9절). 그는 기뻐하며 이익을 계산하지 않고, 예수님의 무릎 앞에 엎드려 자신이 죄인이라고 고백합니다. 자신보다 크고 거룩한 분을 마주할 때 일어나는 이 두려움은 이사야가 하나님의 거룩하심 앞에서 자신의 부정함을 깨달은 장면(사 6:5)과 닮았습니다. 다만 누가가 시몬의 내면을 상세히 설명하지 않으므로, 그의 마음에 어떤 죄의 기억이 떠올랐다고 상상해서는 안 됩니다. 확실한 것은 시몬이 자신에게 주어진 선물보다 자신 앞에 계신 분을 더 크게 인식했다는 사실입니다.","셋째, 예수님은 시몬의 고백을 외면이나 정죄로 끝내지 않으십니다(10–11절). 시몬은 ‘떠나 주십시오’라고 말하지만, 예수님은 ‘두려워하지 마라’고 답하시고 사람들을 얻는 사명을 맡기십니다. 은혜란 죄를 못 본 척하는 것이 아니라, 자신의 자격 없음이 드러난 사람을 예수님이 먼저 부르시는 데서도 나타납니다. 이 부르심은 시몬이 대단한 신앙인이어서 받은 보상이 아닙니다. 이후 누가복음의 십자가와 부활 이야기는 죄인에게 가까이 오시는 그리스도의 은혜가 어떤 길을 통해 완성되는지 더 분명하게 밝힙니다(눅 24:46–47). 그날 어부들이 떠난 것은 실패한 배가 아니라 물고기로 가득 찬 배였습니다. 누가는 그들이 예수님의 선물에 머무르지 않고 예수님 자신을 따랐다는 사실로 이야기를 끝냅니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["예수님은 시몬의 부족함을 먼저 해결하라고 하신 뒤 부르지 않으셨습니다. 자신의 권위를 보여 주시고 죄를 깨닫게 하신 뒤, 두려워하는 사람을 새로운 관계와 사명으로 초대하셨습니다. 그러므로 이 본문을 읽으며 먼저 물어야 할 것은 ‘내가 무엇을 더 성취해야 하는가?’보다 ‘내 앞에 계신 예수님은 어떤 분이신가?’입니다. 그리고 그분의 말씀에 오늘 어떻게 응답할지는 그 다음 질문입니다."]},{"heading":"깊이 읽기 · 절별·원어 보충","paragraphs":["4–5절. 예수님은 ‘깊은 곳으로 가라’고 시몬 한 사람에게 명령하시고, 이어 ‘그물을 내려라’고 여러 사람에게 말씀하십니다. 시몬의 ‘선생님’(ἐπιστάτα)은 예수님의 권위를 인정하는 호칭입니다. 8절의 ‘주님’(κύριε)이라는 호칭과 대비되어 장면의 경외감을 드러내지만, 호칭 하나만으로 시몬이 이 순간부터 예수님의 신성을 완전히 이해했다고 단정할 수는 없습니다.","8절. 핵심은 ‘실패한 사람이 다시 성공했다’보다, 예수님을 마주한 사람이 자신의 죄인 됨을 고백했다는 데 있습니다. 이사야 6장과의 비교는 의미 있는 성경 내 연결이지만, 누가가 두 사건을 동일하게 취급한 것은 아닙니다.","10절. ‘사람들을 붙잡게 될 것이다’의 동사 ζωγρέω는 ‘살아 있는 채로 사로잡다’라는 뜻을 가집니다. 본문은 사람을 조종하거나 강제하는 일을 말하지 않습니다. 어획의 기적은 말씀의 권위 아래 사람들을 하나님 나라로 부르는 사명으로 전환됩니다. 대상인 ‘사람들’에는 남녀 모두가 포함됩니다."]},{"heading":"깊이 읽기 · 설교와 주석의 논증","paragraphs":["존 파이퍼 — 그물이 찢어진 사건이 가리키는 더 큰 사명 — 파이퍼는 2002년 설교 「Breaking Nets, Sinking Boats and Saving Men」에서 누가복음 5장을 ‘물고기를 많이 잡은 기적’ 자체로 끝내지 않습니다. 예수님이 먼저 배에서 하나님의 말씀을 가르치시고, 이어 어부들에게 고기를 잡게 하시며, 마지막에는 사람을 얻는 일을 맡기시는 구조에 주목합니다. 찢어지는 그물과 가라앉을 만큼 가득 찬 배는 그리스도의 능력 아래 사람들이 하나님 나라로 모이게 될 일을 미리 보여 주는 장면입니다. 파이퍼는 이 복음 전도의 능력이 궁극적으로 예수님의 권위에 있으면서도 실제 사람들의 증언과 가르침을 통해 역사한다는 점을 사도행전의 교회 성장과 연결합니다.\n이 사명을 맡은 제자에게 필요한 네 가지 특징도 본문 순서대로 전개합니다. 첫째, 예수님처럼 하나님의 말씀을 가르쳐 사람들에게 복음을 충분히 설명해야 합니다(1–3절). 둘째, 시몬처럼 자신의 경험과 형편이 완벽하지 않아도 예수님의 명령에 응답해야 합니다(4–5절). 셋째, 시몬의 죄 고백처럼 은혜를 자신의 공로로 여기지 않는 겸손이 필요합니다(8절). 넷째, 모든 것을 남기고 주님을 따른 제자들처럼 그리스도를 다른 모든 것보다 귀하게 여겨야 합니다(11절). 파이퍼가 궁극적으로 그리는 모습은 유능한 종교 활동가가 아니라, 그리스도의 은혜를 알고 그분의 말씀과 능력에 의지해 사람들을 섬기는 제자입니다.","R. C. 스프로울 — 죄를 깨닫게 하시는 거룩함과, 떠나지 않으시는 구주 — 스프로울은 2012년 「The Catch of Fish」에서 사건의 무게중심을 8절의 시몬에게 놓습니다. 밤새 헛수고한 전문 어부에게 예수님이 다시 그물을 내리라고 하시는 대목에서, 그는 주님의 명령이 인간의 전문성과 경험에 어떻게 도전하는지를 설명합니다. 설교 도중 신학교 스승에게 들은 일화도 소개합니다. 하나님의 주권을 믿으면서 왜 전도해야 하느냐는 물음 앞에서, 예수님이 명하셨다는 사실 자체가 결코 작은 근거가 아니라는 사실을 배웠다는 것입니다. 따라서 시몬의 순종은 기적의 결과를 다 알아서가 아니라 주님의 권위를 인정하는 행위입니다.\n그러나 스프로울에게 더 중요한 장면은 물고기가 가득한 순간 시몬이 엎드리는 모습입니다. 시몬은 이 풍성함을 더 큰 사업의 기회로 삼자고 제안하는 대신, 자신이 죄인임을 고백하며 주님께 떠나 달라고 합니다. 스프로울은 이것을 거룩하신 분의 현존 앞에서 사람이 느끼는 죄책과 두려움으로 설명합니다. 그리고 십자가가 인간의 죄를 드러내는 표지인 동시에 구원의 소망이라는 점을 연결합니다. 시몬이 정말 필요로 한 분은 떠나 달라고 청한 바로 그 구주이십니다. 예수님은 그를 버리지 않으시고 ‘두려워하지 마라’고 하시며 사명에 동참시키십니다. 그리스도를 만난 사람의 중심이 자신이 얻은 유익에서 주님 자신에게로 옮겨가는 것이 이 설교의 결론입니다.","데럴 복 — 거룩하신 예수님이 죄인을 제자로 부르시는 방식 — 데럴 복의 IVP 누가복음 주석은 예수님의 가르침, 자연을 다스리시는 기적, 제자를 부르시는 일이 한 장면에 모여 있다는 점에 주목합니다. 당시 스승들이 제자들을 모으는 일 자체는 낯설지 않았지만, 예수님이 부르시는 사람들은 종교적 성취로 자신을 증명한 엘리트가 아닙니다. 시몬은 자신의 부족함을 알고도 예수님의 말씀에 응답합니다. 복은 어획의 놀라움을 ‘누가 이런 일을 명할 수 있는가?’라는 질문으로 옮겨갑니다. 예수님 앞에서 자신의 죄를 인정하는 것이 사명의 결격 사유가 아니라, 은혜를 의지하는 제자의 출발점이 됩니다.\n복은 10절의 ‘사람을 붙잡는다’는 표현을 사람을 살리는 사명의 이미지로 풉니다. 일반적인 어획은 물고기의 생명을 끝내지만, 예수님이 맡기시는 일은 사람들을 하나님께로 인도하는 것입니다. 그물 안에 가득 잡힌 물고기보다 더 큰 기적은, 주님 앞에 엎드린 죄인이 은혜를 받아 다른 사람에게 복음을 전하는 사람이 되는 변화입니다.","피터 볼트 — 누가복음 전체에서 보는 이 부르심 — 피터 볼트의 누가복음 주석은 앞선 4장의 흐름을 강조합니다. 예수님은 많은 병을 고치시면서도 하나님 나라의 복음을 전파해야 한다는 보내심의 목적을 분명히 말씀하십니다(4:43). 시몬의 어획 사건은 그 목적이 제자 공동체의 형성으로 확장되는 전환점입니다. 볼트는 시몬의 두려움을 이사야 6장의 거룩함 경험과 나란히 놓고, 예수님의 명령으로 그 두려움이 새로운 사명으로 바뀌는 모습을 읽습니다. 이렇게 시작된 말씀의 확장은 누가복음에서 사도행전으로 이어집니다. 시몬이 한때 떠나 달라고 했던 주님의 증인이 되어 복음을 전하게 되는 미래를 생각하면, 이 장면에서 예수님이 주시는 은혜와 부르심의 크기가 더욱 선명해집니다.","함께 묵상하기 — 네 자료의 강조점은 조금씩 다르지만 모두 독자의 시선을 시몬의 기량보다 예수님의 권위와 거룩함으로 이끕니다. 말씀으로 다가오시는 예수님, 죄를 드러내시는 예수님, 두려움 가운데 있는 사람을 은혜로 부르시는 예수님, 그 사람을 복음의 증인으로 세우시는 예수님은 서로 다른 분이 아닙니다. 그래서 이 장면은 ‘부족한 나도 열심히 하면 성공한다’는 교훈에 그치지 않고, 죄인을 부르시는 예수님이 어떤 분이신지 깊이 바라보게 합니다."]},{"heading":"묵상 질문","paragraphs":["1. 시몬은 물고기를 얻은 순간 오히려 예수님 앞에 엎드립니다. 나는 예수님이 주시는 선물보다 그분 자신을 더 알고 싶어 합니까?","2. 자신의 죄를 깨달은 시몬에게 ‘두려워하지 마라’고 하신 말씀은, 나의 자격 없음과 예수님의 부르심을 어떻게 다시 보게 합니까?"]},{"heading":"기도","paragraphs":["주 예수님, 제 판단과 경험보다 주님의 말씀을 신뢰하도록 가르쳐 주십시오. 저의 죄와 연약함을 숨기지 않고 주님 앞에 나아가게 하시고, 저를 떠나지 않으시는 주님의 은혜를 바라보며 오늘 맡기신 일에 응답하게 하소서. 아멘."]}],"sources":[{"author":"John Piper","title":"Breaking Nets, Sinking Boats and Saving Men","kind":"설교","url":"https://www.desiringgod.org/messages/breaking-nets-sinking-boats-and-saving-men"},{"author":"R. C. Sproul","title":"The Catch of Fish","kind":"설교","url":"https://learn.ligonier.org/sermons/catch-fish"},{"author":"Darrell L. Bock","title":"Come Work with Me: The Gathering of the Disciples","kind":"주석","url":"https://www.biblegateway.com/resources/ivp-nt/Come-Work-Me-Gathering-Disciples"},{"author":"Peter G. Bolt","title":"Luke","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/luke/"}],"preview":false},{"id":"JES-001","track":"JES","title":"세례 받으시는 하나님의 아들","passage":"마 3:13–17","excerpt":"죄 없으신 예수님은 왜 요한에게 세례를 받으셨는가?","bible":"https://www.bible.com/ko/bible/142/MAT.3.RNKSV","verses":[{"n":13,"text":"그때 예수님이 요한에게 세례를 받으시려고 갈릴리에서 요단강으로, 요한에게 오셨다."},{"n":14,"text":"그러나 요한은 예수님을 막으며 말했다. “제가 당신에게 세례를 받아야 하는데, 도리어 당신이 저에게 오십니까?”"},{"n":15,"text":"예수님이 대답하셨다. “지금은 그대로 하여라. 이렇게 해서 우리가 모든 의를 이루는 것이 합당하다.” 그러자 요한이 허락하였다."},{"n":16,"text":"예수님은 세례를 받으시고 곧 물에서 올라오셨다. 보라, 하늘이 열렸고 예수님은 하나님의 영이 비둘기처럼 내려와 자기 위에 임하시는 것을 보셨다."},{"n":17,"text":"그리고 보라, 하늘에서 한 음성이 들려왔다. “이는 내가 사랑하는 아들이다. 내가 그를 기뻐한다.”"}],"sections":[{"heading":"오늘의 질문","paragraphs":["죄인들에게 회개의 세례를 베풀던 요한에게 죄 없으신 예수님이 찾아오셨습니다. 예수님은 왜 그 세례를 받으셔야 한다고 말씀하셨을까요?"]},{"heading":"성경 본문 안내","paragraphs":["본문 비교 읽기: https://www.bible.com/ko/bible/142/MAT.3.RNKSV","그리스어 대조: https://www.biblegateway.com/passage/?search=Matthew%203%3A13-17&version=SBLGNT","평행 본문: 마가복음 1:9–11; 누가복음 3:21–22; 관련 증언 요한복음 1:29–34."]},{"heading":"본문을 깊이 읽기 — 낮아지신 아들을 아버지가 기뻐하십니다","paragraphs":["마태는 앞 장에서 예수님을 아브라함과 다윗의 자손으로 소개하고, 애굽에서 돌아오신 아들로 묘사했습니다(마 1–2장). 3장에서는 세례 요한이 하나님 나라가 가까이 왔다고 선포하며 사람들에게 회개의 열매를 요구합니다. 그 가운데 예수님이 세례를 받으러 오시는 장면은 예상 밖의 사건입니다. 요한이 주님 앞에서 자신이 세례를 받아야 한다고 느끼는 이유도 여기에 있습니다. 요한이 준비하던 길은 마침내 예수님께로 이어집니다.","첫째, 예수님은 자신을 죄인들보다 높은 자리에서 분리하는 방식으로 사역을 시작하지 않으십니다(13–15절). 요한의 세례는 회개와 밀접하게 연결되어 있습니다(3:6, 11). 그러나 예수님이 씻어 내야 할 자신의 죄가 있어서 세례를 받으신 것은 아닙니다. 요한이 마땅히 순서를 바꾸어야 한다고 생각한 자리에 예수님은 몸소 서십니다. 그리고 이유를 “모든 의를 이루기 위해서”라고 밝히십니다. 마태복음에서 ‘의’는 하나님이 원하시는 뜻과 올바른 길을 따르는 일과 연결됩니다(5:6, 10, 20; 6:33). 예수님은 아버지께 순종하는 아들로서 하나님의 구원 계획에 합당한 길을 걸으십니다. 그 길은 죄인들과 관계를 끊는 길이 아니라 그들을 구원하러 가까이 오시는 길입니다.","둘째, 하나님께서는 이 낮아지심을 침묵으로 지나치지 않으십니다(16–17절). 성령께서 비둘기처럼 내려오시고 하늘에서 아버지의 음성이 들립니다. 마태는 놀라운 종교 체험의 장관보다 예수님이 누구이신지를 밝힙니다. 하나님이 사랑하시고 기뻐하시는 아들이 바로 이분입니다. ‘내 아들’이라는 표현은 왕으로 세워진 아들에 관한 시편 2편을, 하나님이 기뻐하시는 종이라는 표현은 이사야 42:1을 떠올리게 합니다. 왕의 존엄과 종의 순종이 예수님 안에서 함께 나타납니다. 그분의 아들 됨은 세례를 받는 순간 처음 생겨난 자격이 아닙니다. 아버지는 이미 사랑하시는 아들을 공개적으로 드러내십니다.","셋째, 세례 장면은 곧이어 광야에서 시험받으실 예수님을 바라보게 합니다(4:1–11). 아버지의 사랑을 받는 아들이 성령의 인도하심으로 광야에 가십니다. 예수님의 순종은 고난이 없는 쉬운 길을 선택하는 것이 아닙니다. 마태는 예수님을 이스라엘의 역사를 되짚으시면서도 불순종을 반복하지 않으실 참된 아들로 소개합니다. 훗날 십자가에 이르기까지 아버지 뜻을 행하시는 이 길을 따라가면, 우리의 소망이 자기 의를 쌓는 일보다 예수님의 신실한 순종에 있다는 사실이 분명해집니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 죄인을 구원하시기 위해 사랑하시는 아들을 보내셨습니다. 아들은 높으신 분이면서도 낮은 자리에 서시고, 성령은 그 사역에 임하시며, 아버지는 그분을 기뻐하신다고 말씀하십니다. 구원은 인간이 하나님께 올라가는 기술이 아니라 하나님께서 그리스도 안에서 우리에게 다가오신 은혜입니다. 우리는 자신이 얼마나 의로운 사람인지 증명하는 것보다 먼저, 모든 의를 이루러 오신 예수님이 누구이신지 바라봅니다."]},{"heading":"묵상 질문","paragraphs":["1. 요한이 세례의 순서를 바꾸어야 한다고 생각한 이유와, 예수님이 이를 허락하라고 하신 이유는 무엇입니까?","2. 아버지의 사랑을 받는 아들이 낮아져 순종하셨다는 사실은 내가 하나님께 받아들여지는 근거를 어떻게 바꾸어 놓습니까?"]},{"heading":"기도","paragraphs":["아버지 하나님, 죄 없으신 아들을 저희에게 보내시고 구원의 길을 열어 주셔서 감사합니다. 자신을 높이기보다 아버지 뜻에 기꺼이 순종하신 예수님을 더욱 알아가게 하소서. 성령의 도우심을 구하며 그리스도의 의를 의지하게 하소서. 아멘."]},{"heading":"깊이 읽기 — 복음주의 설교와 주석의 논증","paragraphs":["R. C. 스프로울, “The Baptism of Jesus” (2012, 누가복음 3:15–22 설교)","스프로울의 강해는 요한의 당혹스러움에서 시작합니다. 세례 요한은 사람들에게 죄를 돌이키라고 외쳤고, 그 세례는 죄를 씻는 상징이었습니다. 그런데 그가 기다리던 메시야는 흠 없는 어린양이십니다. 이때 요한이 “제가 오히려 세례를 받아야 합니다”라고 말하는 것은 단순한 예절이 아니라, 예수님과 죄인 사이의 근본적인 차이를 인정하는 반응입니다. 그렇다면 예수님은 왜 이 자리에 서십니까? 스프로울은 ‘모든 의를 이루려 한다’는 예수님의 답을 하나님의 율법과 뜻에 대한 그리스도의 능동적 순종이라는 신학적 틀로 풉니다. 예수님은 자기 죄를 씻기 위해 물에 들어가신 것이 아니라, 자신이 구원할 백성과 함께 서시며 아버지의 요구를 온전히 순종하십니다.","스프로울은 여기서 칭의와 연결되는 중요한 질문을 던집니다. 죄인이 하나님의 심판 앞에 의롭다고 인정받으려면 무엇이 필요합니까? 단지 죄에 대한 벌이 없어지는 것만 아니라 하나님이 요구하시는 온전한 의가 필요하다는 것입니다. 스프로울은 예수님의 순종이 그 의를 제공한다고 설명하면서, 죄인인 우리가 자기 행위로 하나님 앞에 설 수 없고 그리스도의 의를 의지해야 한다는 복음의 소식을 강조합니다. 세례는 그분의 사역 전체를 대표하는 순종의 한 사건으로 이해됩니다. 설교 후반에 등장하는 성령의 임재와 아버지의 기뻐하시는 음성은, 아들이 아버지께 속하셨으며 구속 사명을 감당하시는 분임을 보여 줍니다. 마태의 표현 ‘모든 의’와 누가의 세례 장면을 함께 읽을 때 이 설교의 논지가 더욱 선명해집니다.","번 포이트레스(Vern Poythress), “The Baptism of Jesus” (The Gospel Coalition)","포이트레스는 예수님의 세례를 세례 요한의 사역, 다른 복음서의 평행 본문, 구약의 성취, 그리스도의 낮아지심이라는 관점에서 설명합니다. 그가 강조하는 첫 질문은 예수님께 죄가 없는데 왜 죄인의 자리에 계셨는가입니다. 예수님은 죄인들에게 거리를 두신 채 회개를 요구하시는 분으로만 오지 않으셨습니다. 그들과 함께 서시고, 마침내 그들의 죄를 담당하시는 구주의 길에 들어서셨습니다. 포이트레스는 이를 자기 비하가 아니라 의도적인 겸손, 구속 사역에 동참하는 행동으로 읽습니다.","두 번째 질문은 하늘이 열리고 성령이 내려오시며 아버지의 음성이 들리는 장면의 의미입니다. 그는 이 현상이 예수님의 정체성과 그분이 성취하실 사명을 밝히는 계시라고 설명합니다. 하나님의 영이 임한다는 사실은 그리스도의 공적 사역이 성령의 능력과 함께 전개됨을 보여 주며, 아버지는 아들의 정체성을 확증하십니다. 예수님의 세례는 개인적인 회심 의식이 아니라 성부·성자·성령의 사역이 드러나는 장면이고, 죄인에게로 가까이 오시는 구주의 사역을 예고합니다.","더글러스 숀 오도널(Douglas Sean O’Donnell), “Matthew” (TGC Bible Commentary, 3:1–17)","오도널은 마태복음의 시작부터 하나님이 구약에서 주신 약속이 어떻게 예수님 안에서 성취되는지를 따라갑니다. 예수님의 족보와 유년기 이야기, 애굽에서 나오심, 광야를 준비하는 요한의 외침은 옛 이스라엘의 역사를 떠올리게 합니다. 그는 요한이 이사야 40장의 길을 준비하는 사람이며 예수님이 그 길에 등장하는 ‘주님’이라는 점을 강조합니다. 따라서 요한이 예수님께 세례받아야 한다고 말한 것은 예수님이 단지 선한 교사보다 크신 분임을 드러냅니다.","그는 이 장면을 예수님이 참된 이스라엘의 아들로서 하나님의 의를 온전히 이루시는 시작이라고 설명합니다. 옛 이스라엘이 광야에서 시험받고 불순종했다면 예수님은 하나님의 뜻을 온전히 따르십니다. 그분의 세례에는 자기 백성과 함께 서시는 연대성과 구원의 길이 압축되어 있습니다. 아버지의 음성이 예수님을 사랑받는 아들로 소개하고, 성령이 임하시는 장면은 세례 뒤의 시험과 그 이후의 사역을 준비합니다. 이처럼 오도널은 본문을 단순한 의식의 모범보다 예수님의 정체성 및 구약 성취를 선언하는 마태복음의 중요한 전환점으로 읽습니다."]},{"heading":"원어와 문맥","paragraphs":["15절 ‘모든 의’(πᾶσαν δικαιοσύνην)는 하나님의 뜻에 합당한 행위를 가리키며, 마태복음 전체에서 의가 거듭 중요한 주제로 나타납니다. ‘지금은 허락하라’는 말씀은 예수님과 요한이 이 상황에서 수행할 역할을 전제합니다.","16절 성령은 ‘비둘기처럼’(ὡσεὶ περιστερὰν) 내려오십니다. 본문이 성령을 영원히 새와 같은 형상의 존재로 규정하는 것은 아닙니다.","17절 ‘사랑하는 아들’과 ‘내가 기뻐한다’는 음성은 시편 2편과 이사야 42:1을 함께 고려하게 합니다. 예수님의 왕적 정체성과 섬기는 사명이 한 장면에 있습니다."]}],"sources":[{"author":"Ligonier Ministries","title":"baptism jesus","kind":"해설","url":"https://learn.ligonier.org/sermons/baptism-jesus"},{"author":"The Gospel Coalition","title":"the baptism of jesus","kind":"해설","url":"https://www.thegospelcoalition.org/essay/the-baptism-of-jesus/"},{"author":"The Gospel Coalition","title":"matthew","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/matthew/"}],"preview":false,"unit_type":"DEEP"},{"id":"JES-002","track":"JES","title":"광야에서 신실하신 아들","passage":"마 4:1–11","excerpt":"시험 앞에서 예수님의 말씀과 순종은 무엇을 드러내는가?","bible":"https://www.bible.com/ko/bible/142/MAT.4.RNKSV","verses":[{"n":1,"text":"그때 예수님은 성령께 이끌려 광야로 가셔서 악마에게 시험을 받으셨다."},{"n":2,"text":"사십 일 밤낮으로 금식하신 뒤 예수님은 배가 고프셨다."},{"n":3,"text":"시험하는 자가 다가와 말했다. “당신이 하나님의 아들이라면, 이 돌들에게 명령하여 빵이 되게 해 보시오.”"},{"n":4,"text":"예수님이 대답하셨다. “기록되어 있다. ‘사람이 빵으로만 살지 않고 하나님의 입에서 나오는 모든 말씀으로 산다.’”"},{"n":5,"text":"그때 악마는 예수님을 거룩한 성으로 데려가 성전의 높은 곳에 세웠다."},{"n":6,"text":"그리고 말했다. “당신이 하나님의 아들이라면 아래로 몸을 던지시오. 기록되어 있지 않소? ‘그분이 너를 위해 천사들에게 명령하실 것이며, 그들이 손으로 너를 받들어 네 발이 돌에 부딪히지 않게 할 것이다.’”"},{"n":7,"text":"예수님이 말씀하셨다. “또 기록되어 있다. ‘주 너의 하나님을 시험하지 마라.’”"},{"n":8,"text":"다시 악마는 예수님을 아주 높은 산으로 데려가 세상의 모든 나라와 그 영광을 보여 주었다."},{"n":9,"text":"그리고 말했다. “엎드려 나에게 경배하면 이 모든 것을 주겠소.”"},{"n":10,"text":"예수님이 말씀하셨다. “사탄아, 물러가라. 기록되어 있다. ‘주 너의 하나님께 경배하고 그분만 섬겨라.’”"},{"n":11,"text":"그러자 악마가 예수님을 떠났고, 보라, 천사들이 와서 그분을 섬겼다."}],"sections":[{"heading":"오늘의 질문","paragraphs":["아버지께서 사랑하시는 아들이라 선언하신 예수님은 왜 곧바로 시험의 광야로 가셨습니까? 그분은 어떻게 아버지를 신뢰하셨습니까?"]},{"heading":"성경 본문 안내","paragraphs":["본문 비교 읽기: https://www.bible.com/ko/bible/142/MAT.4.RNKSV","평행 본문: 누가복음 4:1–13; 마가복음 1:12–13","구약 배경: 신명기 6:13, 16; 8:2–3; 출애굽기 4:22–23","문맥 — 사랑받는 아들이 광야로","마태복음 3장 마지막에서 하늘의 음성은 예수님을 하나님이 사랑하시고 기뻐하시는 아들이라 선언합니다. 다음 장에서 같은 아들이 성령의 인도 아래 광야에 들어가 시험받습니다. 아들 됨은 고통이 전혀 없는 길을 보장하는 표지가 아닙니다. 하나님을 신뢰하고 순종해야 하는 자리에서 드러나는 관계입니다. 이 장면은 이스라엘의 광야 사십 년, 모세의 말씀, 첫 사람의 불순종을 함께 생각하게 합니다."]},{"heading":"본문을 깊이 읽기 | 아들 됨을 자기 이익을 위해 이용하지 않으신 주님","paragraphs":["첫째, 예수님은 굶주림 속에서도 자신의 필요가 아버지의 말씀보다 앞서도록 하지 않으십니다(1–4절). 사탄의 유혹은 단지 빵을 먹는 일이 죄라는 주장이 아닙니다. 하나님의 아들이라는 사실을 사용해 아버지께 의지하는 삶에서 벗어나 자기 필요를 스스로 보장하라는 제안입니다. 예수님은 신명기 8:3을 인용하십니다. 광야에서 만나를 주신 하나님을 기억하라는 이 말씀은 생존의 근거가 음식 자체보다 하나님의 돌보시는 말씀에 있음을 보여 줍니다. 예수님의 금식과 굶주림은 실제적이지만, 그분은 필요를 핑계 삼아 하나님을 불신하지 않으십니다.","둘째, 예수님은 하나님의 약속을 자신을 과시하는 도구로 사용하지 않으십니다(5–7절). 사탄도 시편 91편의 말씀을 인용합니다. 성경 구절을 말한다는 사실만으로 하나님의 뜻에 순종하는 것이 아닙니다. 사탄은 보호하신다는 약속을 근거로 하나님을 시험하도록 부추깁니다. 예수님은 신명기 6:16으로 응답하십니다. 하나님께서 선하시다는 것을 확인받으려고 위험에 뛰어들어 표적을 요구하는 태도는 믿음이 아닙니다. 참된 신뢰는 하나님을 자기 행동에 복종시키려는 시도가 아니라 그분의 말씀에 자신을 맡기는 것입니다.","셋째, 예수님은 아버지께 대한 경배를 세상의 영광과 맞바꾸지 않으십니다(8–11절). 사탄은 권세와 화려함을 보여 주며 단 한 번의 경배를 요구합니다. 문제의 중심은 얼마나 큰 나라를 갖느냐가 아니라 누구를 경배하느냐입니다. 예수님은 신명기 6:13을 인용하시며 하나님만 섬기겠다고 밝히십니다. 그분은 지름길로 왕관을 취하는 방식이 아니라 아버지의 뜻에 순종하고 십자가로 나아가시는 길을 선택하십니다. 마태복음 마지막에서 부활하신 예수님은 하늘과 땅의 모든 권세를 받으셨다고 선언하십니다(28:18). 광야의 유혹은 그 권세를 하나님 아닌 자에게 경배하여 얻으라는 제안이었습니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님께서는 자신의 사랑하는 아들을 시험 한가운데서도 버리지 않으십니다. 예수님은 한때 실패했던 이스라엘과 달리 하나님의 말씀을 붙잡고 순종하십니다. 그러므로 이 본문은 우리에게 단순한 유혹 대처 방법 세 가지를 알려 주는 데서 끝나지 않습니다. 우리의 불순종과 대조되는 참된 아들의 신실하심을 보여 줍니다. 우리는 그분의 순종을 바라보고 그분이 주시는 은혜를 의지하여 시험 가운데 하나님을 신뢰하는 법을 배웁니다."]},{"heading":"묵상 질문","paragraphs":["1. 예수님이 사탄에게 응답하실 때 반복해서 사용하신 성경은 무엇이며, 그 말씀은 그분의 정체성을 어떻게 보여 줍니까?","2. 내가 하나님을 신뢰한다고 말하면서 실제로는 하나님께 내 계획을 증명하라고 요구하는 부분은 없습니까?"]},{"heading":"기도","paragraphs":["사랑하시는 아들을 보내신 하나님, 저의 필요와 두려움이 주님의 말씀보다 앞서지 않게 하소서. 시험 가운데 끝까지 아버지를 신뢰하신 예수님의 순종을 바라보며, 하나님만을 경배하게 하소서. 아멘."]},{"heading":"깊이 읽기 | 실제 설교와 주석","paragraphs":["더글러스 숀 오도널 — 「Matthew」(The Gospel Coalition Bible Commentary), “Tempted in the Wilderness (4:1–11)”","오도널은 세례와 광야 시험 사이에 놓인 ‘하나님의 아들’이라는 호칭을 해설의 열쇠로 삼습니다. 마태복음 3장의 선언은 예수님의 정체성을 알려 주었고, 4장의 시험은 이 아들이 실제로 어떠한 순종을 보이시는지 드러냅니다. 오도널이 주목하는 것은 광야·사십 일·신명기 인용의 반복입니다. 이스라엘은 광야에서 배고픔과 두려움을 경험했으나 하나님을 거듭 시험했습니다. 반면 예수님은 같은 광야의 형편 속에서도 하나님께 충실하십니다.","그는 세 유혹을 ‘자기 필요를 우선시하는 능력 사용’, ‘성경을 이용해 아버지의 보호를 강요하는 태도’, ‘경배를 교환하여 권세를 취하는 제안’으로 따라갑니다. 특히 두 번째 유혹에서 사탄도 성경을 사용하지만, 예수님은 성경을 또 다른 말씀으로 바르게 읽으십니다. 마지막 유혹에는 왕이 될 자의 영광과 십자가의 길이 대조됩니다. 이러한 구조에서 예수님은 단지 하나님 말씀으로 시험을 이기는 기술을 가르치는 교사가 아니라, 실패한 이스라엘을 대신하여 순종하시는 참된 아들로 드러납니다.","존 파이퍼 — 「Man Shall Not Live on Bread Alone」(1995)","파이퍼는 예수님이 세 시험에서 모두 신명기를 인용하신 사실을 질문으로 삼습니다. 왜 구약의 다른 본문도 많은데 신명기 6장과 8장이었을까요? 그는 신명기 8장에서 이스라엘이 광야에서 사십 년 동안 배고픔과 시험을 통과했던 일을 읽고, 예수님의 사십 일 금식이 이스라엘 역사를 다시 걷는 행위임을 강조합니다. 이스라엘이 하나님의 말씀을 신뢰하지 못했던 자리에서 예수님은 참된 아들로 충실하십니다.","파이퍼에게 금식은 단순히 굶는 능력을 과시하는 것이 아닙니다. 참된 생명의 원천이신 하나님께 자기 필요를 의탁하는 훈련과 연결됩니다. 예수님은 배고픔이 거짓된 필요라고 주장하지 않으십니다. 오히려 더 깊은 생명의 근거를 먼저 붙잡으십니다. 파이퍼는 이를 통해 성도가 말씀을 마음에 저장하고, 어려운 순간 그 말씀을 따라 하나님을 더 소중히 여기는 삶을 권면합니다. 하지만 그 권면의 토대는 먼저 광야에서 순종하신 예수님의 모습에 있습니다.","원어·해석 점검","마태복음 4:1의 시험(πειρασθῆναι)은 하나님이 주관하시는 시험의 자리와 악마가 행하는 유혹을 구별하여 읽어야 합니다(약 1:13). 4:4의 신명기 인용은 빵 자체의 가치를 부정하지 않고 말씀에 대한 궁극적 신뢰를 가르칩니다. 사탄이 인용한 시편 91편을 마태복음 4:7의 신명기 말씀과 함께 읽어야 성경을 왜곡하는 방식과 성경에 순종하는 방식이 드러납니다."]}],"sources":[{"author":"The Gospel Coalition","title":"matthew","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/matthew/"},{"author":"John Piper","title":"man shall not live on bread alone","kind":"설교","url":"https://www.desiringgod.org/messages/man-shall-not-live-on-bread-alone"}],"preview":false,"unit_type":"DEEP"},{"id":"JES-003","track":"JES","title":"와서 보라","passage":"요 1:35–51","excerpt":"예수님은 사람들을 어떻게 만나고 자신을 드러내시는가?","bible":"https://www.bible.com/ko/bible/142/JHN.1.RNKSV","verses":[],"sections":[{"heading":"오늘의 질문","paragraphs":["예수님을 찾아온 제자들에게 그분은 무엇을 물으시고 무엇을 보여 주십니까?","본문 전체 읽기","요한복음 1:35–51: https://www.bible.com/ko/bible/142/JHN.1.RNKSV","앞 본문: 세례 요한의 증언(1:19–34). 다음 본문: 가나의 첫 표적(2:1–12). 관련 본문: 창세기 28:10–17, 누가복음 5:1–11.","배경과 맥락","요한복음 첫머리에서 세례 요한은 자신이 빛이 아니라 빛을 증언하는 사람이라고 밝힙니다. 1:29–34에서 그는 예수님을 세상 죄를 지고 가시는 하나님의 어린양으로 소개합니다. 이튿날 자신의 제자들 앞에서 다시 예수님을 가리키자 그들은 예수님을 따라갑니다. 이어 안드레, 시몬, 빌립, 나다나엘이 차례로 등장하고, 각 사람이 예수님을 부르는 호칭과 예수님이 자신을 드러내시는 말씀이 쌓입니다."]},{"heading":"본문을 깊이 읽기","paragraphs":["첫째, 예수님을 따르는 일은 그분이 누구신지 듣는 데서 시작됩니다(35–39절). 세례 요한은 자기에게 충성할 제자를 끝까지 붙들지 않습니다. 오히려 자신의 사명이 가리키는 분에게 사람을 보냅니다. 예수님은 두 사람이 따르는 것을 보시고 무엇을 찾느냐고 물으십니다. 그들은 머무시는 곳을 묻고, 예수님은 직접 와서 보라고 초대하십니다. 요한은 그들이 예수님과 시간을 보낸 사실을 구체적으로 기록합니다. 그리스도에 대한 믿음은 막연한 삶의 개선법을 얻는 일이 아니라 그분의 말씀을 듣고 인격적으로 알아가는 관계에서 자랍니다.","둘째, 예수님은 사람을 만나시면서 그 사람의 미래까지 아시는 분으로 드러나십니다(40–46절). 안드레는 자신의 형제 시몬을 데려오고 예수님은 그에게 ‘게바’라는 이름을 주십니다. 이는 당장 시몬의 성품이 완성되었다는 평가가 아니라 그를 통해 이루실 사명을 내다보게 합니다. 빌립은 나다나엘을 찾아 모세와 예언자들이 기록한 분을 만났다고 말합니다. 나다나엘은 나사렛에서 무슨 좋은 것이 나겠느냐고 의심하지만, 빌립은 상대를 논쟁으로 꺾기보다 ‘와서 보라’고 초대합니다. 제자들의 증언은 자신의 지혜를 자랑하는 것이 아니라 예수님께 사람의 시선을 향하게 하는 역할을 합니다.","셋째, 예수님은 제자들이 생각한 것보다 더 크신 분입니다(47–51절). 나다나엘은 자신을 미리 아시는 예수님의 말씀에 놀라 ‘하나님의 아들’, ‘이스라엘의 왕’이라고 고백합니다. 예수님은 거기서 그치지 않으시고 더 큰 일을 보게 될 것이라고 약속하십니다. 하늘이 열리고 천사들이 인자 위에 오르내릴 것이라는 말씀은 야곱이 하나님과 하늘을 연결하는 사닥다리를 본 창세기 28장을 떠올리게 합니다. 요한은 예수님 안에서 하나님께서 사람에게 다가오시는 결정적인 길이 열렸다는 사실을 보여 줍니다. 예수님은 단순한 스승보다 크신, 하나님을 드러내시는 분이십니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["예수님은 자신을 찾는 사람들에게 관심을 두시며, 그들보다 먼저 그들을 아십니다. 처음 제자들은 예수님을 완전히 이해하지 못했습니다. 그럼에도 주님은 그들을 부르시고, 함께 머무르게 하시며, 자신이 어떤 분인지 점차 드러내십니다. 믿음은 내가 이미 그리스도를 충분히 이해했기 때문에 시작되는 것이 아니라 그분의 부르심을 듣고 더 깊이 알아가는 길입니다.","주요 절","1:38–39 ‘무엇을 찾느냐?’는 예수님의 질문이자 제자의 마음을 드러내는 문장입니다. ‘와서 보라’는 즉각 모든 답을 알려 주겠다는 약속보다 함께 머물며 그분을 알아가는 초청입니다.","1:42 ‘게바’는 아람어로 바위를 가리키며 그리스어 ‘베드로’와 연결됩니다. 이름을 주신 사건을 시몬의 현재 성품에 대한 단순 칭찬으로 읽지 않습니다.","1:51 ‘인자’와 하늘을 오르내리는 천사의 모습은 창세기 28장의 야곱 환상을 배경으로 합니다."]},{"heading":"깊이 읽기 | 신앙의 선배들에게 배우기","paragraphs":["안드레아스 쾨스텐베르거(Andreas J. Köstenberger), 「John」, The Gospel Coalition Bible Commentary, 1:35–51.","쾨스텐베르거는 첫 제자의 부르심을 다른 복음서의 호숫가 제자 소명과 경쟁하는 이야기로 다루지 않습니다. 요한복음에만 보존된 세례 요한의 증언은 일부 제자들이 예수님에 대해 이미 듣고 준비되어 있었음을 보여 줍니다. 예수님의 부르심이 뜬금없는 한순간의 선택이 아니라 세례 요한의 증언과 만남을 통해 전개된다는 것입니다. 주석은 ‘머물다’라는 평범한 동사가 이후 요한복음에서 그리스도의 말씀 안에 거하는 관계를 나타내는 중요한 표현으로 발전한다고 짚습니다. 지금 본문에서는 먼저 예수님과 그날 실제로 함께 머문 사건 자체를 존중해야 합니다.","쾨스텐베르거는 또한 나다나엘의 고백을 1:34의 하나님의 아들 증언과 이어 읽습니다. 빌립이 나다나엘에게 들려준 모세와 예언자의 약속, 나다나엘의 회의, 예수님의 특별한 앎과 고백은 독자가 예수님의 정체성을 단계적으로 알아가도록 만듭니다. 마지막 51절은 야곱의 환상을 배경으로, 하늘과 땅이 만나는 중심이 이제 예수님이라는 놀라운 진술에 이릅니다. 주석은 이름이 밝혀지지 않은 첫 두 제자 중 한 사람이 요한복음 저자였다는 생각과 나다나엘이 바돌로매라는 전통적 동일시를 가능성으로만 제시합니다. 본문이 직접 밝히지 않은 인물의 정체를 확정하지 않는 것이 좋습니다.","원전: https://www.thegospelcoalition.org/commentary/john/"]},{"heading":"묵상 질문","paragraphs":["1. 내가 예수님에게 얻기를 원하는 것과 예수님 자신을 알고 싶은 마음은 어떻게 다릅니까?","2. 내가 누군가에게 그리스도를 소개할 때 빌립처럼 ‘와서 보라’고 초대할 수 있는 방식은 무엇일까요?"]},{"heading":"기도","paragraphs":["제 삶을 먼저 아시는 예수님, 제가 주님을 나의 필요를 채우는 방법으로만 대하지 않게 하소서. 주님의 말씀에 머물며 주님이 누구신지 더 깊이 알아가게 하시고, 다른 사람도 주님께 나아오도록 정직하게 증언하게 하소서. 아멘."]}],"sources":[{"author":"The Gospel Coalition","title":"john","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/john/"}],"preview":false,"unit_type":"DEEP"},{"id":"ACT-002","track":"ACT","title":"말씀을 붙들고 기다리는 제자들","passage":"행 1:12–26","excerpt":"성령의 약속 앞에서 공동체는 무엇을 하는가?","bible":"https://www.bible.com/ko/bible/142/ACT.1.RNKSV","verses":[],"sections":[{"heading":"오늘의 질문","paragraphs":["예수님이 승천하신 뒤 성령의 약속을 기다리던 공동체는 무엇에 의지했고, 왜 가룟 유다를 대신할 사람을 세웠을까요?"]},{"heading":"성경 본문 안내","paragraphs":["사도행전 1:12–26 전체: https://www.bible.com/ko/bible/142/ACT.1.RNKSV","그리스어 대조: https://www.biblegateway.com/passage/?search=Acts%201%3A12-26&version=SBLGNT","이 회차는 BRIDGE 유형으로, 전체 본문을 링크에서 직접 읽고 아래의 연결 해설을 읽도록 설계했습니다. 본문을 읽지 않았다면 요약문만 읽은 것으로 성경 읽음 완료를 처리하지 않습니다.","본문의 흐름을 따라 읽기","12–14절 | 돌아와 함께 기도하는 사람들","제자들은 감람산에서 예루살렘으로 돌아옵니다. 이는 성령을 기다리며 예루살렘을 떠나지 말라는 주님의 명령(1:4)에 대한 순종입니다. 누가는 열한 사도와 여자들, 예수님의 어머니 마리아, 예수님의 형제들이 한마음으로 기도에 힘썼다고 기록합니다. 예수님이 승천하셨다는 사실이 공동체를 각자 흩어지게 하지 않았습니다. 그들은 기도하며 약속하신 하나님을 기다립니다. 이것은 아무 계획 없이 시간을 보내는 수동적인 대기가 아니라, 주님의 말씀과 공동체를 붙드는 기다림입니다.","15–20절 | 실패와 배신도 하나님의 약속을 끊지 못합니다","베드로는 약 120명의 사람 앞에서 유다의 배신과 죽음을 말합니다. 누가는 그 끔찍한 이야기를 숨기지 않습니다. 예수님이 친히 택하신 열두 사람 가운데 하나가 그분을 배반했습니다. 그렇다면 사도들이 전할 소식과 하나님의 계획은 실패한 것입니까? 베드로는 성령께서 다윗의 입을 통해 미리 말씀하신 성경이 성취되어야 했다고 말하며, 시편 69:25과 109:8을 인용합니다. 하나님이 악한 선택을 선하게 여기셨다는 뜻이 아닙니다. 인간의 배신이 실제 죄라는 사실을 분명히 하면서도, 그 사건이 하나님의 구원 계획을 무너뜨리지 못한다는 사실을 선언합니다.","21–26절 | 부활의 증인을 다시 세우시는 주님","베드로는 대신 세울 사도의 조건을 제시합니다. 요한의 세례 때부터 예수님의 승천까지 그들과 함께 다니며 예수님의 부활을 증언할 수 있는 사람이어야 합니다. 공동체는 요셉 바사바와 맛디아를 세우고 모든 사람의 마음을 아시는 주님께서 택하신 사람을 보여 달라고 기도합니다. 제비를 뽑은 결과 맛디아가 열한 사도와 함께 열두 사도로 인정받습니다. 여기에서 사도직은 단순한 조직의 빈자리를 메우는 역할보다, 부활을 직접 본 증인으로서 교회의 기초를 세우는 역할입니다.","이 본문에서 만나는 하나님","배신과 상실을 경험한 공동체도 하나님 말씀의 신실하심을 따라 새롭게 세워질 수 있습니다. 사도들이 부활하신 주님을 눈으로 볼 수 없는 순간에도, 그분은 자기 백성을 버려두지 않으십니다. 제자들은 말씀을 읽고 기도하고 증언할 사람을 세우며, 아버지의 약속인 성령이 임할 날을 기다립니다. 그러므로 기도하는 기다림은 주님의 통치 밖에 남겨진 시간이 아닙니다.","앞뒤 본문과의 연결","앞 회차 행 1:1–11에서는 승천하신 예수님이 성령을 약속하고 증인의 사명을 맡기십니다. 이 회차는 그 약속을 기다리며 사도의 증언 공동체가 준비되는 과정입니다. 다음 회차 행 2:1–13에서 약속된 성령이 임하시며, 이어 베드로가 예수님의 죽음과 부활을 선포합니다."]},{"heading":"묵상 질문","paragraphs":["1. 예수님의 약속을 기다리는 동안 제자들이 실제로 했던 일은 무엇이며, 그 일이 주님에 대한 신뢰를 어떻게 보여 줍니까?","2. 성경은 유다의 배신을 숨기지 않습니다. 사람의 실패에도 하나님의 약속이 무너지지 않는다는 사실이 어떻게 다가옵니까?"]},{"heading":"기도","paragraphs":["약속을 지키시는 하나님, 기다림의 시간에도 주님의 말씀을 붙들게 하소서. 사람의 실패와 연약함을 정직하게 보면서도 살아 계신 주님의 다스리심을 잊지 않게 하시고, 기도하며 복음의 증언에 충실하게 하소서. 아멘."]},{"heading":"깊이 읽기 | 복음주의 주석에서 배우기","paragraphs":["앨런 J. 톰프슨, “Acts” — The Gospel Coalition Bible Commentary, 1:12–26","톰프슨은 이 단락의 중심에 승천하신 그리스도의 계속되는 통치를 둡니다. 누가는 성령 강림을 기록하기 전에 왜 사도들의 수를 회복하는 사건에 시간을 할애할까요? 예수님이 선택하신 열두 명 중 한 사람이 배반한 사실은 이스라엘의 회복과 복음의 확장을 약속하신 주님의 말씀이 실패한 것처럼 보이게 할 수 있습니다. 그러나 베드로가 인용하는 시편은 하나님의 뜻이 인간의 배신으로 취소되지 않는다는 사실을 보여 줍니다. 누가는 유다의 행위가 죄였다는 점을 흐리지 않으면서, 하나님께서 역사와 성경의 말씀을 통하여 그 모든 일을 주관하신다는 큰 그림을 제시합니다.","특히 톰프슨은 앞부분의 공동 기도와 뒷부분의 선택 기도를 서로 연결합니다. 제자들이 처음 한 일은 승천하신 주님의 말씀에 순종하여 예루살렘에 모이는 일이었습니다. 이제 그들은 사도를 선택할 때도 자기 눈에 더 유능해 보이는 사람만 내세우지 않고 ‘사람들의 마음을 아시는 주님’께 의지합니다. 열두 사도의 복구는 단순한 숫자 맞추기가 아닙니다. 예수님이 선택하신 사도들이 이스라엘의 열두 지파와 연결된 증언 공동체를 구성하겠다는 주님의 약속(눅 22:30)이 살아 있음을 보여 줍니다.","그는 새로운 사도의 자격에도 주목합니다. 이 사도의 일은 예수님의 지상 사역을 직접 함께 경험하고 부활을 직접 본 사람으로서 증언하는 것이었습니다. 따라서 오늘 모든 교회 직책을 이 방식으로 선출해야 한다거나, 제비뽑기가 일반적인 기독교 의사 결정의 표준이라는 결론은 이 사건의 독특한 역할을 놓치는 것입니다. 톰프슨은 마지막으로 열두 사도 중 하나를 선택하시는 주체가 공동체의 손 너머에 계신 부활하신 주님이라고 설명합니다. 사도행전의 앞뒤 장면을 잇는 중심 인물이 여전히 예수님이시라는 것입니다.","성경 안에서 더 깊이 읽을 연결","시편 69:25; 109:8 — 베드로가 인용한 시편. 신약의 사도들이 다윗의 고난과 원수에 관한 시를 그리스도의 고난 사건에 어떻게 연결했는지 비교할 수 있습니다.","누가복음 22:28–30 — 열두 사도의 역할에 관한 예수님의 약속.","잠언 16:33 — 제비를 뽑는 일을 하나님의 주권과 연결하는 지혜의 말씀. 사도행전 1장을 현대 교회의 보편적 절차 지침으로 단순화하지 말고, 사도라는 고유한 직분의 문맥에서 읽어야 합니다."]}],"sources":[{"author":"The Gospel Coalition","title":"acts","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/acts/"}],"preview":false,"unit_type":"BRIDGE"},{"id":"ACT-003","track":"ACT","title":"성령이 오신 날","passage":"행 2:1–13","excerpt":"성령의 오심이 예수님의 약속을 어떻게 성취하는가?","bible":"https://www.bible.com/ko/bible/142/ACT.2.RNKSV","verses":[{"n":1,"text":"오순절 날이 이르렀을 때 그들이 모두 한곳에 함께 있었다."},{"n":2,"text":"갑자기 하늘에서 세찬 바람이 불어오는 것 같은 소리가 났고 그들이 앉아 있던 온 집을 가득 채웠다."},{"n":3,"text":"불꽃처럼 갈라진 혀들이 그들에게 나타나더니 각각의 사람 위에 하나씩 머물렀다."},{"n":4,"text":"그들은 모두 성령으로 가득 차 성령이 말하게 하시는 대로 다른 언어들로 말하기 시작했다."},{"n":5,"text":"그때 예루살렘에는 하늘 아래 모든 민족에서 온 경건한 유대인들이 머물고 있었다."},{"n":6,"text":"이 소리가 나자 많은 사람들이 모여들었고 각자 자기 언어로 제자들이 말하는 것을 듣고 어리둥절해졌다."},{"n":7,"text":"그들이 놀라고 감탄하며 말했다. “보시오, 말하는 이들이 모두 갈릴리 사람들이 아닙니까?"},{"n":8,"text":"그런데 어찌하여 우리 각자가 태어나면서부터 쓰는 자기 언어로 듣고 있습니까?"},{"n":9,"text":"우리는 파르티아 사람, 메디아 사람, 엘람 사람이며 메소포타미아, 유대, 카파도키아, 폰토스와 아시아,"},{"n":10,"text":"프리기아와 팜필리아, 이집트와 구레네 근처 리비아 지역에 사는 사람들입니다. 로마에서 온 체류자도 있으며,"},{"n":11,"text":"유대인과 유대교로 들어온 사람, 크레타 사람과 아라비아 사람도 있습니다. 그런데 우리가 우리의 언어로 그들이 하나님의 위대한 일들을 말하는 것을 듣습니다.”"},{"n":12,"text":"모두 놀라며 어찌할 바를 몰라 서로 말했다. “이것이 무슨 뜻입니까?”"},{"n":13,"text":"그러나 다른 사람들은 비웃으며 말했다. “저 사람들은 새 술에 취했소.”"}],"sections":[{"heading":"오늘의 질문","paragraphs":["성령께서 오셨을 때 사람들은 왜 여러 언어로 말하기 시작했습니까? 사람들의 귀에 들린 것은 무엇이었습니까?"]},{"heading":"성경 본문 안내","paragraphs":["본문 비교 읽기: https://www.bible.com/ko/bible/142/ACT.2.RNKSV","앞 본문: 행 1:4–8, 1:12–26 / 다음 본문: 행 2:14–36","문맥과 배경","예수님은 승천 전에 제자들에게 예루살렘을 떠나지 말고 아버지께서 약속하신 성령을 기다리라고 명하셨습니다(행 1:4–8). 제자들은 말씀과 기도 가운데 그 약속을 기다렸습니다. 오순절은 유월절 뒤의 유대 절기로 여러 지역에 흩어져 살던 유대인들이 예루살렘에 모였습니다. 누가는 절기와 언어가 다른 사람들을 세밀히 기록하여 하나님께서 이루시는 일이 특정 지역과 한 집단 안에 갇히지 않음을 보여 줍니다."]},{"heading":"본문을 깊이 읽기 | 약속하신 성령이 오시다","paragraphs":["첫째, 성령 강림은 예수님의 약속이 성취된 사건입니다(1–4절). 제자들이 특별한 기법으로 성령을 불러내지 않았습니다. 하늘에서 오는 소리와 불꽃 같은 혀의 모습은 하나님이 직접 임하시는 사건임을 드러냅니다. 바람이나 불이 곧 성령이라는 뜻도 아닙니다. 그 표현은 성령의 오심을 감각적으로 경험하게 하지만, 이야기의 중심은 제자들이 성령으로 충만해졌다는 사실입니다. 높임받으신 예수님께서 아버지께 받은 약속을 자신의 백성에게 부어 주시는 일은 이어지는 베드로의 설교에서 분명해집니다(2:33).","둘째, 성령은 사람들에게 하나님이 하신 일을 알아듣게 하십니다(5–11절). 누가는 언어를 이해하지 못하는 혼란 자체보다, 지역과 언어가 다른 사람들이 자기 말로 제자들의 증언을 알아듣는 놀라움을 강조합니다. 사람들은 갈릴리 출신인 제자들에게서 자신들이 쓰던 말이 들리는 이유를 설명할 수 없었습니다. 그런데 들린 내용은 제자들의 위대함이나 특별한 능력을 자랑하는 말이 아니라 ‘하나님의 위대한 일들’이었습니다(11절). 성령의 은사는 그 자체로 사람을 높이는 도구가 아니라 하나님이 행하신 일을 드러내는 선물이었습니다.","셋째, 놀라운 일을 보았다는 사실만으로 누구나 같은 반응을 보이지 않습니다(12–13절). 어떤 사람들은 진지하게 뜻을 묻지만 다른 이들은 조롱합니다. 성령의 역사에는 언제나 누구도 반박할 수 없는 감각적 확신만 남는 것이 아닙니다. 누가는 사건 뒤에 베드로의 성경 해석과 예수님의 죽음·부활에 대한 선포를 배치합니다(2:14–36). 사건의 의미는 하나님의 말씀을 통해 설명됩니다. 그러므로 이 본문을 읽으며 초자연적 현상을 추구하는 데만 머물지 않고, 성령께서 누구를 증언하시고 무엇을 선포하게 하시는지를 살펴야 합니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 약속하신 성령을 주셔서 자신의 백성이 예수 그리스도의 일을 증언하게 하십니다. 성령의 선물은 인간이 국가나 언어의 경계를 넘어 복음에 귀 기울일 수 있게 하시는 하나님의 은혜입니다. 교회는 스스로 대단한 이야기를 만들어 세상에 내놓는 모임이 아니라 하나님의 큰일을 전하도록 부름받은 공동체입니다."]},{"heading":"묵상 질문","paragraphs":["1. 여러 언어로 들린 말의 내용이 ‘하나님의 위대한 일들’이었다는 사실은 성령의 사역을 어떻게 설명합니까?","2. 뜻을 묻는 사람들과 조롱하는 사람들의 서로 다른 반응을 볼 때, 하나님의 말씀을 듣는 나의 태도를 어떻게 점검할 수 있습니까?"]},{"heading":"기도","paragraphs":["약속하신 성령을 보내신 하나님, 저희의 능력을 드러내는 데 마음을 빼앗기지 않고 예수님을 증언하게 하소서. 낯선 이들의 언어와 삶을 존중하며 하나님이 하신 위대한 일을 진실하게 나누는 교회가 되게 하소서. 아멘."]},{"heading":"깊이 읽기 | 원전 설교와 주석","paragraphs":["앨런 J. 톰프슨 — 「Acts」(The Gospel Coalition Bible Commentary), 2:1–13","톰프슨은 사도행전 1장이 예수님의 승천을 강조한 뒤 2장에서 하늘로부터 임하는 소리를 기록한다는 문학적 연결을 주목합니다. 성령의 강림은 예수님이 떠난 뒤 시작된 별개의 신앙 운동이 아니라, 부활하여 높임받으신 주님의 약속이 실행되는 사건입니다. 오순절이라는 절기의 맥락, 하나님의 임재를 떠올리게 하는 바람과 불의 이미지, 각 사람에게 임하는 성령의 묘사는 구약에서 하나님이 자기 백성 가운데 함께하신다는 약속을 새로운 단계에서 보여 줍니다.","톰프슨은 ‘모든 나라에서 온 유대인들’과 긴 지역 목록이 사건의 선교적 방향을 제시한다고 설명합니다. 여기에는 아직 예루살렘에 머문 유대인들이 중심에 있지만, 이 복음은 이미 여러 지역의 언어로 선포됩니다. 하나님께서 이스라엘에게 주신 약속이 예수님 안에서 성취되었고, 그 소식은 점차 사마리아와 이방인에게까지 전파됩니다. 이어지는 베드로의 설교가 요엘서와 시편을 인용하는 것은 이 현상이 제멋대로 나타난 힘이 아니라 성경에 약속된 하나님의 역사임을 밝힙니다.","존 파이퍼 — 「Tongues of Fire and the Fullness of God」(1990)","파이퍼는 설교를 시작하며 성령의 능력은 제자들의 사명, 곧 땅끝까지 증인이 되는 일과 연결된다는 전제를 밝힙니다. 그에게 오순절은 예수님의 약속이 실제로 이루어진 첫 큰 성령 강림 사건입니다. 그는 오순절이 추수의 절기라는 점에 주목하여, 곧이어 수많은 사람이 회개하고 교회에 들어오는 장면을 선교적 추수와 연결합니다.","설교의 중간에서 그는 ‘갑자기’라는 표현을 강조합니다. 성령은 인간이 정한 시간이나 기술에 조종되지 않으며, 그분의 능력은 하나님께 속합니다. 이어 바람과 불의 이미지를 하나님 임재의 표현으로 설명하면서, 가장 중요한 것이 특정한 감각적 현상의 반복이 아니라 하나님이 얼마나 위대하신지를 경험하고 담대하게 증언하는 일이라고 말합니다. 그 근거로 11절의 ‘하나님의 큰일’을 듭니다. 여러 언어는 이 증언을 열방에 전달하려는 하나님의 뜻을 보여 줍니다. 파이퍼는 이러한 특별한 성령의 능력이 오늘날의 복음 전파에도 필요하다고 적용하는데, 이 대목은 그의 성령 사역에 관한 설교적 입장으로 읽고 본문에서 모든 시대에 동일한 현상이 반드시 일어난다는 주장과는 구별해야 합니다."]},{"heading":"원어와 문맥","paragraphs":["2절은 ‘바람’ 자체가 아니라 바람이 불어오는 것 ‘같은 소리’를, 3절은 불 자체가 아니라 불 ‘같은 혀’를 묘사합니다. 4절의 ‘다른 언어들’과 6–11절의 ‘자기 언어’는 이 단락 안에서 서로 연결됩니다. 일부 기독교 전통은 오늘날의 방언과의 관계를 다르게 설명하므로, 여기서는 누가가 명시한 다국어 이해와 하나님의 큰일 증언을 중심에 둡니다."]}],"sources":[{"author":"The Gospel Coalition","title":"acts","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/acts/"},{"author":"John Piper","title":"tongues of fire and the fullness of god","kind":"설교","url":"https://www.desiringgod.org/messages/tongues-of-fire-and-the-fullness-of-god"}],"preview":false,"unit_type":"DEEP"},{"id":"ACT-004","track":"ACT","title":"부활하신 예수를 주와 그리스도로","passage":"행 2:14–36","excerpt":"베드로의 설교에서 예수님은 누구신가?","bible":"https://www.bible.com/ko/bible/142/ACT.2.RNKSV","verses":[],"sections":[{"heading":"오늘의 질문","paragraphs":["오순절의 놀라운 현상을 보았던 사람들이 꼭 들어야 했던 것은 어떤 소식입니까?","본문 전체 읽기","사도행전 2:14–36: https://www.bible.com/ko/bible/142/ACT.2.RNKSV","앞 본문: 성령 강림(2:1–13). 다음 본문: 회개와 공동체(2:37–47). 함께 읽기: 요엘 2:28–32; 시편 16:8–11; 시편 110:1.","배경과 맥락","성령께서 오신 날 제자들이 여러 언어로 하나님의 큰일을 말하자, 사람들은 놀라거나 술에 취한 것이라 조롱했습니다. 베드로는 그 사건을 설명하기 위해 이스라엘의 성경을 펴고 예수님의 죽음과 부활을 선포합니다. 누가는 단지 성령의 능력이 어떤 현상을 만들어 냈는지보다, 성령께서 누구를 증언하도록 하셨는지를 보여 줍니다. 베드로의 설교는 요엘서와 두 시편을 따라 예수님이 누구이신지를 밝힙니다."]},{"heading":"본문을 깊이 읽기","paragraphs":["첫째, 성령 강림은 하나님이 약속하신 마지막 때의 시작을 알립니다(14–21절). 베드로는 제자들이 술에 취한 것이 아니라고 설명한 뒤 요엘 선지자의 말을 인용합니다. 이전에는 특별한 직분을 받은 사람이 하나님의 영을 통한 사역을 드러낸 경우가 많았지만, 여기서는 아들딸, 젊은이와 노인, 남녀 종을 포함한 하나님의 백성에게 성령을 부어 주신다는 약속이 강조됩니다. 이것은 인간의 신분과 경계를 넘어 하나님이 자기 백성에게 말씀하시고 일하신다는 뜻입니다. 그러나 현상의 경이로움보다 중요한 것은 마지막에 ‘주님의 이름을 부르는 사람은 구원을 얻는다’는 초청입니다.","둘째, 그 구원의 소식은 사람들에게 죽임당하셨지만 하나님께서 살리신 예수님을 가리킵니다(22–28절). 베드로는 예수님의 능력 있는 사역을 회상하며, 그분이 하나님의 정하신 뜻과 미리 아심 가운데 넘겨지셨다고 말합니다. 동시에 예수님을 십자가에 못 박은 사람들의 책임도 흐리지 않습니다. 하나님의 주권은 인간의 악을 선하다고 선언하지 않습니다. 하나님은 죽음을 깨뜨리고 예수님을 일으키셨습니다. 베드로는 다윗의 시편 16편을 통해 하나님의 거룩한 이를 죽음의 부패에 버려두지 않으시리라는 소망을 예수님의 부활과 연결합니다.","셋째, 높임받으신 예수님이 성령의 선물을 부어 주셨습니다(29–36절). 베드로는 다윗 자신의 무덤이 알려져 있었다는 점을 지적하며, 그의 시가 궁극적으로 다윗의 후손으로 오실 그리스도를 가리킨다고 설명합니다. 예수님이 실제로 살아나신 것은 사도들이 목격한 사실입니다. 시편 110편의 ‘내 오른편에 앉으라’는 말씀은 높아지신 메시아의 통치를 선언합니다. 따라서 33절에서 예수님이 아버지께 성령을 받으시고 지금 사람들이 보고 듣는 것을 부어 주셨다고 밝힙니다. 설교의 결론은 ‘하나님이 이 예수님을 주와 그리스도가 되게 하셨다’는 선포입니다. 이는 예수님이 이전에는 참된 하나님의 아들이 아니셨다가 뒤늦게 신성이 생겼다는 뜻이 아니라, 십자가와 부활과 높임을 통해 그분의 주권이 공적으로 선포되었다는 말입니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["성부 하나님은 약속을 이루시고, 예수 그리스도는 죽음을 이기고 높임받으시며, 성령은 이 예수님을 증언하게 하십니다. 교회의 생명력은 놀라운 경험을 반복해서 만들어 내는 데 있지 않고, 부활하신 예수님이 지금도 주님이시라는 소식에 있습니다. 이 설교를 들은 사람들은 자기 죄를 깨닫고 다음 단락에서 회개와 세례에 대한 질문을 던지게 됩니다.","주요 절","2:17 ‘마지막 날들’은 구원의 약속이 예수님과 성령의 사역에서 결정적인 성취 단계에 들어섰다는 선언입니다.","2:23 하나님의 미리 정하심과 예수님을 죽인 사람의 죄책은 동시에 진술됩니다.","2:33–36 성령을 부어 주시는 분은 높임받으신 예수님이며, 베드로의 결론은 예수님의 주 되심입니다."]},{"heading":"깊이 읽기 | 신앙의 선배들에게 배우기","paragraphs":["앨런 J. 톰프슨(Alan J. Thompson), 「Acts」, The Gospel Coalition Bible Commentary, 2:14–36.","톰프슨은 베드로가 오순절을 단독의 신비로운 현상으로 남겨 놓지 않는 데 주목합니다. 그는 요엘의 예언을 인용하여 성령의 오심이 하나님의 약속과 구원 역사의 흐름 속에 있음을 보여 줍니다. 요엘 인용에는 하나님의 백성에게 성령이 주어진다는 보편성뿐 아니라 심판과 주의 이름을 부르는 자의 구원이라는 주제가 포함됩니다. 베드로는 성령 강림을 체험한 제자들의 위대함을 설명하려는 것이 아니라, 하나님께서 예수님을 통하여 무엇을 하셨는지를 밝히는 것입니다.","톰프슨은 설교의 중심이 22절부터 예수님께로 모인다고 분석합니다. 그리스도의 죽음은 하나님의 구원 목적 바깥의 우발적 패배가 아니면서도, 십자가를 행한 사람들에게 책임을 묻는 사건입니다. 시편 16편은 다윗 자신을 넘어 부활하실 메시아를 가리키고, 시편 110편은 그분이 하나님의 오른편에서 통치하신다는 사실을 드러냅니다. 그래서 성령 강림의 원인과 의미가 33절에서 분명해집니다. 눈에 보이는 현상은 하늘에서 통치하시는 예수님이 성령을 보내셨기 때문에 일어났습니다. 이 설교는 교회의 정체성을 ‘부활하신 왕 예수님에 대한 증언’으로 세웁니다. 후속 단락의 회개 요청 역시 이 결론에서 비롯됩니다.","원전: https://www.thegospelcoalition.org/commentary/acts/"]},{"heading":"묵상 질문","paragraphs":["1. 베드로는 성령 강림의 의미를 설명할 때 왜 예수님의 죽음·부활·높임을 함께 선포했을까요?","2. 나의 신앙적 관심이 특별한 경험보다 살아 계신 예수님의 말씀과 통치를 향하고 있습니까?"]},{"heading":"기도","paragraphs":["부활하신 예수 그리스도, 주님이 지금도 하나님 오른편에서 다스리시는 분임을 믿습니다. 성령의 능력을 내 자랑으로 삼지 않게 하시고, 세상 가운데 주님의 죽음과 부활을 진실하게 증언하게 하소서. 아멘."]}],"sources":[{"author":"The Gospel Coalition","title":"acts","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/acts/"}],"preview":false,"unit_type":"DEEP"},{"id":"EPI-002","track":"EPI","title":"복음을 부끄러워하지 않는 이유","passage":"롬 1:8–17","excerpt":"복음은 어떻게 하나님의 구원 능력이 되는가?","bible":"https://www.bible.com/ko/bible/142/ROM.1.RNKSV","verses":[{"n":8,"text":"먼저, 예수 그리스도로 말미암아 여러분 모두에 관하여 나의 하나님께 감사드립니다. 여러분의 믿음이 온 세상에 알려지고 있기 때문입니다."},{"n":9,"text":"내가 그 아들의 복음 안에서 내 영으로 섬기는 하나님이 나의 증인이십니다. 나는 여러분을 끊임없이 기억하며,"},{"n":10,"text":"언제나 기도 가운데 하나님의 뜻 안에서 어떻게든 마침내 여러분에게 갈 길이 열리기를 간구합니다."},{"n":11,"text":"내가 여러분을 보기를 간절히 바라는 것은 어떤 영적인 은사를 나누어 주어 여러분을 굳건하게 하고자 하기 때문입니다."},{"n":12,"text":"다시 말해, 여러분과 나 사이에 있는 서로의 믿음을 통해 여러분 가운데서 함께 격려를 얻고자 하는 것입니다."},{"n":13,"text":"형제자매 여러분, 내가 여러 차례 여러분에게 가려고 계획했지만 지금까지 길이 막혔다는 것을 여러분이 모르기를 원하지 않습니다. 다른 민족들 가운데서와 같이 여러분 가운데서도 얼마간의 열매를 얻으려는 것이었습니다."},{"n":14,"text":"나는 헬라인과 헬라 문화 밖의 사람들, 지혜 있는 사람과 지혜롭지 못한 사람 모두에게 빚진 사람입니다."},{"n":15,"text":"그래서 내게는 로마에 있는 여러분에게도 복음을 전하려는 간절한 마음이 있습니다."},{"n":16,"text":"나는 복음을 부끄러워하지 않습니다. 이 복음은 믿는 모든 사람을 구원하는 하나님의 능력이기 때문입니다. 먼저는 유대인에게, 그리고 헬라인에게도 그렇습니다."},{"n":17,"text":"복음 안에서 하나님의 의가 믿음으로부터 믿음에 이르도록 드러납니다. 기록된 바, “의인은 믿음으로 살 것이다”라고 한 것과 같습니다."}],"sections":[{"heading":"오늘의 질문","paragraphs":["복음을 전하는 일이 인간의 눈에 연약하고 수치스럽게 보일 때, 바울은 어떤 근거로 이 복음이 하나님의 능력이라고 확신했을까요?"]},{"heading":"성경 본문 안내","paragraphs":["그리스어 본문: https://www.biblegateway.com/passage/?search=Romans%201%3A8-17&version=SBLGNT"]},{"heading":"본문을 깊이 읽기 — 복음의 능력은 어디서 오는가","paragraphs":["바울은 로마에 교회를 세운 사람이 아닙니다. 그럼에도 그는 그곳 성도들을 위해 기도하며 그들을 만나기를 간절히 원합니다. 1:1–7에서 예수 그리스도가 누구이신지를 소개한 뒤, 8–15절에서는 자신이 왜 그들에게 가려고 하는지 설명합니다. 이어 16–17절에서는 로마서 전체의 중심 주제를 선포합니다. 그 가운데 반복해서 나타나는 것은 바울의 뛰어난 능력이 아니라 예수 그리스도의 복음입니다.","첫째, 복음의 사람들은 서로의 믿음으로 함께 격려받습니다(8–12절). 바울은 로마 교회의 믿음이 알려진 것을 감사하며 그들을 위해 계속 기도한다고 말합니다. 그들을 방문하려는 이유는 자신이 그들 위에 군림하기 위해서가 아닙니다. 물론 그는 사도로서 자신의 사명을 분명하게 알고 있습니다. 그러나 12절에서 그는 그 방문이 ‘서로의 믿음’을 통해 ‘함께 위로받는’ 시간이 되기를 원한다고 설명합니다. 사도에게조차 다른 성도의 믿음에서 얻는 위로가 필요합니다. 하나님이 이루시는 복음의 공동체는 몇몇 뛰어난 사람이 나머지를 일방적으로 돕는 조직이 아닙니다.","둘째, 복음은 문화적 우월감의 울타리를 넘어섭니다(13–15절). 바울은 헬라인과 비헬라인, 지혜 있는 자와 지혜롭지 못한 자에게 모두 빚을 졌다고 말합니다. 이것은 그들이 바울에게 개인적인 돈을 빌려주었다는 뜻이 아닙니다. 그리스도로부터 복음 전파의 사명을 받은 자로서, 그 소식을 특정 문화나 사회 계층의 사람들만의 소유로 묶어 둘 권리가 없다는 것입니다. 로마 제국의 중심 도시에서도 복음은 가장 힘 있는 자의 지적 교양이나 정치적 영향력을 자랑하는 소식이 아닙니다. 바울은 이미 믿음이 알려진 로마 성도들에게도 그리스도를 선포하고 싶어 합니다.","셋째, 바울의 담대함은 복음의 내용이 하나님의 구원 능력이기 때문입니다(16–17절). 예수 그리스도는 십자가에서 처형되셨습니다. 그분을 주님이라고 선포하는 일은 세상의 지위와 영광을 바라보는 사람에게 수치스럽고 무력하게 보일 수 있습니다. 그런데 바울은 복음 자체가 하나님의 능력이라고 말합니다. 그 이유는 복음 안에서 하나님의 의가 나타나기 때문입니다. 하나님은 죄를 가볍게 덮어 둔 채 죄인을 구원하시는 분이 아닙니다. 이어지는 1:18–3:20은 모든 사람이 죄 아래 있음을 밝히고, 3:21–26은 하나님이 그리스도 안에서 의를 나타내시며 믿는 자를 의롭다 하신다는 사실을 더 자세히 설명합니다. 바울의 확신은 전도 방법의 성공률이 아니라 그리스도의 십자가와 부활을 통해 나타난 하나님의 구원 행위에 있습니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 인간이 자랑할 만한 힘을 소유한 사람에게만 구원을 맡기시지 않습니다. 그리스도의 복음 자체를 통해 믿는 사람을 구원하십니다. 그러므로 그 복음에 대한 우리의 믿음은 자신의 믿음이 얼마나 강한지 과시하는 태도가 아니라 하나님이 베푸신 의와 은혜에 의지하는 태도입니다. 또한 이 복음은 사람들을 경쟁자로 갈라놓지 않고 서로를 세우고 위로하는 공동체로 부르십니다."]},{"heading":"묵상 질문","paragraphs":["1. 바울은 로마 성도들에게 자신도 격려받고 싶다고 말합니다. 내가 다른 사람의 믿음에서 배우고 위로받는 일을 어려워하는 이유는 무엇입니까?","2. 복음이 하나님의 능력이라는 말씀은, 사람들이 나를 어떻게 평가할지 두려워하는 마음을 어떻게 다시 보게 합니까?"]},{"heading":"기도","paragraphs":["주 하나님, 사람의 평가나 자랑보다 예수 그리스도의 복음을 더 귀하게 여기게 하소서. 다른 성도의 믿음에서 위로를 받고 그들을 격려하며, 문화와 지위를 넘어 누구에게나 주님의 은혜를 진실하게 나누게 하소서. 죄인을 구원하시는 주님의 의를 신뢰합니다. 아멘."]},{"heading":"깊이 읽기 — 설교와 주석의 실제 논증","paragraphs":["존 파이퍼, “Not Ashamed of the Gospel” (1998)","파이퍼는 로마서 1:15의 ‘로마에 가서 복음을 전하려는 열심’과 16절의 ‘복음을 부끄러워하지 않는다’는 선언을 연결합니다. 바울은 단지 의무감 때문에 전하겠다고 하지 않습니다. 복음의 진실성과 가치를 알기에 그것을 전하기를 원합니다. 파이퍼는 먼저 수치심이 왜 발생하는지 일상적인 예를 듭니다. 사람은 자신이 믿었던 것이 거짓으로 드러나거나, 자신이 기대했던 것이 무너질 때 수치를 느낍니다. 그렇다면 십자가에서 죽으신 분을 구주라고 말하는 것이 인간의 판단에서는 어리석게 보일 수 있어도, 바울은 왜 그렇게 여기지 않을까요?","파이퍼의 답은 복음에 담긴 능력이 인간의 위신을 지키는 데 있지 않다는 것입니다. 복음이 하나님의 진정한 구원 능력이라는 사실을 바울이 알기 때문입니다. 죄에서 건짐받는 구원은 사회의 인정이나 강한 이미지와 비교할 수 없이 크며, 그 복음의 진실성은 다른 사람의 평가로 결정되지 않습니다. 파이퍼는 담대함을 원래 수치심이 없는 성격이나 타고난 용기로 환원하지 않습니다. 그리스도의 복음을 부끄러워하지 않을 근거는 복음이 무엇이며 하나님이 그 안에서 무엇을 이루셨는지 아는 데 있습니다. 전도가 자기 과시가 아니라 그리스도의 능력에 대한 증언이 되는 이유도 여기에 있습니다.","존 파이퍼, “How Does the Gospel Save Believers?” Part 1–3 (1998)","파이퍼는 16절의 선언을 다시 질문으로 바꿉니다. 복음이 구원을 베푸는 하나님의 능력이라는 사실은 알겠는데, **어떻게** 죄인을 구원합니까? 바울이 다음 절에서 ‘하나님의 의가 나타난다’라고 답하는 구조를 따라가야 한다고 주장합니다. 하나님의 사랑이 복음에 나타난다는 사실은 분명합니다(롬 5:8). 그러나 여기서 바울은 그 사랑을 먼저 설명하는 대신 하나님의 ‘의’를 말합니다. 왜 그렇습니까? 죄인을 구원하는 일이 하나님의 거룩함과 공의에 어긋나는 일이 아니기 때문입니다.","파이퍼는 로마서 3:21–26으로 시선을 옮겨 바울이 뒤에서 어떻게 그 주장을 전개하는지를 보여 줍니다. 하나님은 죄인을 의롭다고 선언하시면서 자신의 의를 희생시키지 않으십니다. 그리스도 안에서 죄를 다루시고, 믿는 자가 받을 의를 나타내십니다. 파이퍼는 여기서 하박국 2:4의 ‘의인은 믿음으로 살 것이다’를 중요하게 읽습니다. 예언자는 악과 심판의 위기 속에서 하나님의 신실하심을 믿으라고 부름받았고, 바울은 그 말씀을 복음의 믿음과 구원에 연결합니다. 이 논증을 통해 파이퍼는 믿음이 하나님께 의로움을 구매하는 공로가 아니라, 하나님께서 은혜로 주시는 의를 받는 길임을 강조합니다. 죄인이 스스로 자신의 의를 만들지 못할 때에도 구원이 가능한 것은 복음 안에서 의로우신 하나님이 행동하시기 때문입니다.","원문 1: https://www.desiringgod.org/messages/how-does-the-gospel-save-believers","원문 2: https://www.desiringgod.org/messages/how-does-the-gospel-save-believers-part-2","원문 3: https://www.desiringgod.org/messages/how-does-the-gospel-save-believers-part-3","도니 레이 매시스(Donny Ray Mathis II), “Romans” (The Gospel Coalition Bible Commentary), 1:8–17","매시스는 로마서의 긴 서론을 바울의 구체적인 관계와 선교 계획 속에 배치합니다. 8–15절에서 바울이 로마 교인들에게 기도하고 서로 위로받기를 원하는 이유는, 이 교회가 유대인과 이방인 그리스도인이 함께 살아가는 제국 수도의 공동체이기 때문입니다. 바울은 자신의 가르침을 전달하는 동시에 그들의 믿음에서 유익을 얻기를 원합니다. 매시스는 바울이 여러 번 방문하려 했다는 말이 관계를 세우는 진심을 보여 준다고 설명합니다. 로마의 성도들은 이미 복음 안에 있지만 더욱 굳건해져야 합니다. 헬라인과 비헬라인 모두에게 복음을 전할 빚을 졌다는 말은 복음이 인간의 문화적 구분과 우월성을 넘어선다는 주제도 준비합니다.","이어 매시스는 16–17절을 로마서 전체 논증의 제목과 같은 구절로 읽습니다. 바울이 그리스도의 복음을 부끄러워하지 않는 이유는, 십자가에 못 박히셨다가 부활하신 예수님이 참된 왕이시기 때문입니다. 그 복음은 유대인과 이방인을 모두 구원할 수 있습니다. 매시스가 강조하는 하나님의 의에는 언약을 지키시는 하나님의 신실하심과 죄인을 올바르게 판결하고 구원하시는 의로움이 함께 있습니다. 바울이 하박국 2:4를 인용하는 것도 하나님의 약속에 대한 믿음이 위기의 시대에도 생명의 길임을 보여 주기 위해서입니다. 따라서 17절의 ‘믿음으로부터 믿음에 이르도록’이라는 난해한 말은 뒤의 칭의 논증과 이어져서 읽어야 합니다.","원어와 논증의 연결","12절 ‘함께 격려받다’(συμπαρακληθῆναι)는 바울의 사도적 권위와 별개로 성도들 사이의 상호 격려를 나타냅니다.","14절 헬라인과 ‘야만인’(βαρβάροις)의 대조는 당시 그리스 문화의 언어를 반영합니다. 한국어로 사람을 낮춰 부르는 말처럼 직접 적용하지 않고 문화권의 경계를 넘는 사도로서의 의무를 읽습니다.","16절 ‘구원을 위한 하나님의 능력’은 복음의 실제 구원 효력을 가리키며, 믿는 자 모두를 향합니다.","17절 ‘하나님의 의’(δικαιοσύνη θεοῦ)와 ‘믿음에서 믿음으로’(ἐκ πίστεως εἰς πίστιν)에는 해석적 논의가 있습니다. 먼저 로마서 1–4장의 바울 자신의 전개를 따라 읽고, 구원과 하나님 언약의 신실하심을 함께 살펴야 합니다."]}],"sources":[{"author":"John Piper","title":"not ashamed of the gospel","kind":"설교","url":"https://www.desiringgod.org/messages/not-ashamed-of-the-gospel"},{"author":"John Piper","title":"how does the gospel save believers","kind":"설교","url":"https://www.desiringgod.org/messages/how-does-the-gospel-save-believers"},{"author":"John Piper","title":"how does the gospel save believers part 2","kind":"설교","url":"https://www.desiringgod.org/messages/how-does-the-gospel-save-believers-part-2"},{"author":"John Piper","title":"how does the gospel save believers part 3","kind":"설교","url":"https://www.desiringgod.org/messages/how-does-the-gospel-save-believers-part-3"},{"author":"The Gospel Coalition","title":"romans","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/romans/"}],"preview":false,"unit_type":"DEEP"},{"id":"EPI-003","track":"EPI","title":"진리를 억누르는 사람","passage":"롬 1:18–32","excerpt":"우상숭배는 하나님을 아는 인간의 삶을 어떻게 왜곡하는가?","bible":"https://www.bible.com/ko/bible/142/ROM.1.RNKSV","verses":[{"n":18,"text":"불의로 진리를 억누르는 사람들의 모든 불경건과 불의에 대하여 하나님의 진노가 하늘로부터 드러나고 있다."},{"n":19,"text":"하나님에 관하여 알 수 있는 것이 그들 가운데 분명하기 때문이다. 하나님이 그들에게 그것을 분명히 보이셨다."},{"n":20,"text":"그분의 보이지 않는 것들, 곧 영원한 능력과 신성이 세상 창조 때부터 만들어진 것들을 통해 생각으로 깨달아 분명하게 보인다. 그러므로 그들은 변명할 수 없다."},{"n":21,"text":"그들은 하나님을 알면서도 하나님을 하나님으로 영화롭게 하지 않았고 감사하지도 않았다. 오히려 생각이 헛되게 되었고 깨닫지 못하는 마음이 어두워졌다."},{"n":22,"text":"스스로 지혜롭다고 주장하면서 어리석은 자가 되었고,"},{"n":23,"text":"썩지 않으시는 하나님의 영광을 썩는 사람과 새와 네 발 달린 짐승과 기어 다니는 것들의 형상과 바꾸었다."},{"n":24,"text":"그래서 하나님은 그들을 그들 마음의 욕망에 따른 부정함에 내버려 두셔서, 그들이 서로 자기 몸을 욕되게 하도록 하셨다."},{"n":25,"text":"그들은 하나님의 진리를 거짓과 바꾸고 창조주보다 피조물을 경배하고 섬겼다. 창조주께서는 영원히 찬양받으실 분이다. 아멘."},{"n":26,"text":"이런 까닭에 하나님은 그들을 수치스러운 욕정에 내버려 두셨다. 그들의 여자들은 자연스러운 성관계를 자연에 어긋나는 것으로 바꾸었고,"},{"n":27,"text":"마찬가지로 남자들도 여자와의 자연스러운 관계를 버리고 서로를 향한 욕망으로 불타올라 남자가 남자와 더불어 부끄러운 일을 행하며, 자기들의 그릇된 길에 해당하는 결과를 자신 안에 받았다."},{"n":28,"text":"그들이 하나님을 인정하여 아는 것을 옳게 여기지 않았으므로 하나님도 그들을 타락한 생각에 내버려 두셔서 마땅하지 않은 일을 하도록 하셨다."},{"n":29,"text":"그들은 온갖 불의, 악함, 탐욕, 악의로 가득하고 시기, 살인, 다툼, 속임, 악독으로 가득한 자들이며 수군거리는 사람들이다."},{"n":30,"text":"비방하는 사람들, 하나님을 미워하는 사람들, 무례한 사람들, 교만한 사람들, 자랑하는 사람들, 악을 꾸며 내는 사람들, 부모에게 불순종하는 사람들이다."},{"n":31,"text":"분별없는 사람들, 약속을 저버리는 사람들, 정이 없는 사람들, 자비 없는 사람들이다."},{"n":32,"text":"이런 일을 행하는 사람들이 죽음에 합당하다는 하나님의 의로운 판결을 알면서도, 그런 일을 할 뿐 아니라 행하는 사람들을 좋게 여기기까지 한다."}],"sections":[{"heading":"오늘의 질문","paragraphs":["인간이 참하나님을 예배하지 않을 때 무슨 일이 일어납니까? 바울은 왜 인간의 여러 죄를 열거하기 전에 ‘하나님의 영광을 다른 것과 바꾸었다’는 문제를 먼저 지적합니까?"]},{"heading":"성경 본문 안내","paragraphs":["본문 비교 읽기: https://www.bible.com/ko/bible/142/ROM.1.RNKSV","앞 본문: 로마서 1:16–17 / 다음 본문: 로마서 2:1–16","문맥 — 복음이 하나님의 능력인 까닭","바울은 로마서 1:16–17에서 복음이 구원하는 하나님의 능력이며 그 안에 하나님의 의가 드러난다고 말했습니다. 이어 ‘왜 그 구원이 필요한가?’라는 질문에 답하기 시작합니다. 1:18–32는 인간이 하나님을 섬기는 대신 피조물을 예배하고 그 결과 관계와 삶이 무너지는 모습을 묘사합니다. 이 단락은 특정 사람들을 도덕적으로 조롱하라고 쓰인 글이 아닙니다. 다음 장은 남을 판단하는 사람도 스스로 변명할 수 없음을 지적하며(2:1), 바울은 결국 유대인과 이방인이 모두 죄 아래 있다고 결론짓습니다(3:9)."]},{"heading":"본문을 깊이 읽기 | 감사가 멈춘 자리에서 시작된 교환","paragraphs":["첫째, 바울은 죄의 문제를 단순히 정보 부족으로 보지 않습니다(18–21절). 하나님은 피조세계를 통해 자신의 영원한 능력과 신성을 드러내셨습니다. 그러나 사람은 하나님을 영화롭게 하거나 감사하기보다 불의 가운데 진리를 억누릅니다. ‘진리를 억누른다’는 말에는 하나님을 인정할 때 자신의 삶을 그분께 내맡겨야 한다는 사실을 피하려는 의지의 문제가 있습니다. 바울이 문제 삼는 것은 학문의 수준이나 지적 능력 자체가 아닙니다. 하나님을 향해 마땅히 드려야 할 영광과 감사를 인간이 거부한다는 것입니다.","둘째, 우상숭배는 하나님의 자리를 피조물에게 내어주는 교환입니다(22–25절). 바울은 세상을 만든 분과 세상 안의 형상을 구별합니다. 모든 피조물은 좋은 선물이지만, 그것을 예배의 대상으로 삼는 순간 선물을 주신 분을 대신하게 됩니다. ‘바꾸었다’는 반복되는 동사는 로마서 첫머리의 신학적 중심입니다. 사람은 경배할 대상을 없애 버리는 대신 다른 대상을 세웁니다. 따라서 우상은 돌이나 나무로 만든 상만을 가리키는 문제가 아니라, 명예·권력·소유·자기 의를 궁극적인 의지의 대상으로 삼는 태도에까지 질문을 던집니다.","셋째, 하나님의 진노는 때로 인간이 택한 길의 결과를 겪도록 내버려 두시는 모습으로 나타납니다(24–32절). 바울은 세 차례 ‘하나님이 그들을 내버려 두셨다’고 말합니다(24, 26, 28절). 하나님이 죄를 기뻐하시거나 죄악의 직접적 수행자가 되셨다는 뜻이 아닙니다. 인간이 창조주의 질서를 거절할 때 몸과 인간관계, 판단과 공동체에 실제 파괴가 일어나는 것을 바울은 심판의 한 형태로 묘사합니다. 여기에는 성관계에 관한 진술도 있으며, 뒤로 갈수록 탐욕과 시기, 비방과 교만, 부모에 대한 불순종, 무정함과 자비 없음까지 함께 열거됩니다. 바울의 목록을 일부 죄만 골라 다른 사람을 정죄하는 도구로 삼는다면 바로 다음 장의 경고를 놓치게 됩니다. 그의 궁극적인 목적은 모든 인간이 하나님의 의와 은혜를 필요로 한다는 사실을 드러내는 것입니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 자기 영광을 피조물에게 양도하시는 분이 아닙니다. 그분은 세계를 창조하고 자신을 나타내시며, 인간이 바른 관계로 그분을 알고 감사하도록 지으셨습니다. 하나님의 진노는 그 선하심에 무관심한 분의 감정이 아니라 진리를 거부하고 서로를 파괴하는 죄를 심판하시는 거룩한 반응입니다. 바울은 이 어두운 진단을 독립된 결론으로 제시하지 않습니다. 복음 안에서 죄인을 의롭다 하시는 하나님의 은혜를 밝히기 위한 논증의 첫 단계로 제시합니다(3:21–26). 그래서 이 본문을 읽을 때 필요한 태도는 다른 사람을 향한 우월감보다 자신의 마음을 살피는 회개입니다."]},{"heading":"묵상 질문","paragraphs":["1. 내가 하나님께 받은 것을 기뻐하면서도 그것을 하나님보다 더 소중하게 삼는 순간은 언제입니까?","2. 바울의 죄 목록을 읽을 때 어떤 죄는 크게 보고 자신의 탐욕·교만·무자비함은 작게 여기지는 않습니까?"]},{"heading":"기도","paragraphs":["창조주시며 의로우신 하나님, 제 마음이 피조물을 주님의 자리에 놓는 어리석음에서 돌이키게 하소서. 영광과 감사를 받기에 합당하신 하나님을 알게 하시고, 다른 사람을 판단하기보다 나 자신이 복음의 은혜를 필요로 하는 죄인임을 기억하게 하소서. 예수 그리스도의 이름으로 기도합니다. 아멘."]},{"heading":"깊이 읽기 | 실제 설교와 주석의 논증","paragraphs":["도니 레이 매시스 — 「Romans」(The Gospel Coalition Bible Commentary), “Idolatry That Destroys Communion with God and Neighbors (1:18–32)”","매시스는 1:18의 하나님의 진노를 바로 앞절의 구원하는 의와 나란히 놓습니다. 복음이 왜 구원을 가져오는 능력인지를 이해하려면 인간이 어떤 위험에 놓여 있는지 알아야 한다는 것입니다. 그는 이 단락을 로마 교회의 유대인과 이방인 사이의 긴장 속에서도 읽습니다. 바울의 고발은 눈에 띄는 한 집단만의 죄를 강조하려는 말이 아니라 하나님을 알면서도 그분을 예배하지 않는 인간의 보편적 문제를 드러냅니다.","매시스는 우상숭배가 개인의 내면에서 끝나지 않고 공동체를 파괴하는 데 주목합니다. 진리를 억누르고 창조주를 피조물과 바꾸는 사건은 사람의 판단과 행동, 다른 사람을 대하는 방식을 왜곡합니다. '내버려 두셨다'라는 표현은 하나님이 죄를 사소하게 여기신다는 뜻이 아니라 죄가 낳는 파괴가 심판의 한 부분이라는 것을 가리킵니다. 이어지는 목록에는 탐욕, 거짓, 무정함 등 일상 관계를 무너뜨리는 죄가 넓게 포함됩니다. 그 결과 로마서 2장의 위선적인 판단에 관한 비판과 3장의 모두 죄인이라는 결론이 준비됩니다. 따라서 1장은 복음 없이 남을 정죄하는 자의 자리를 만들어 주지 않습니다.","존 파이퍼 — 「The Wrath of God Against Holding Down the Truth」(1998)","파이퍼는 1:18을 인간이 자기 삶을 더 좋게 포장하고 불편한 사실을 피하려는 성향과 연결하여 해설합니다. 그는 정치인만 특별히 사실을 왜곡하는 것이 아니라 모든 사람이 자기 잘못은 부드럽게 설명하고 다른 사람의 잘못은 거칠게 말할 수 있다고 지적합니다. 이것은 그가 로마서 2:1을 함께 읽는 이유입니다. 본문이 다른 사람들을 향한 손쉬운 정죄로 변질되는 것을 막고, 우리 모두가 진리를 피하는 경향을 가지고 있음을 드러냅니다.","파이퍼는 이어 하나님에 대한 진리가 단순한 지적 정보보다 깊다는 점을 강조합니다. 하나님의 존재와 능력을 인정하면 우리는 그분을 영화롭게 하고 감사하며 살아야 합니다. 그런데 죄에 대한 사랑과 자기 독립성을 지키려는 마음이 진리를 왜곡하게 합니다. 그는 그래서 해결책이 단지 더 많은 지식을 획득하는 데 있지 않고 새 마음과 복음의 의에 있다고 주장합니다. 그의 설교는 마지막에 1:16–17로 돌아와, 진리를 억누르는 죄인의 소망은 그리스도의 죽음과 부활 안에서 믿음으로 받는 하나님의 의라고 강조합니다.","존 파이퍼 — 「The First Dark Exchange: Idolatry」(1998)","파이퍼는 1:21–23에서 '바꾸었다'라는 말의 의미를 길게 묵상합니다. 문제는 인간이 모든 가치를 버렸다는 데 있지 않습니다. 인간이 영원하신 하나님의 영광보다 유한한 피조물의 형상을 더 귀하게 여기게 되었다는 것입니다. 그는 바울이 성적 죄와 여러 사회적 죄를 나열하기 전에 먼저 하나님을 영화롭게 하지 않고 감사하지 않는 태도를 언급한다는 사실을 강조합니다. 교회의 중요한 죄 진단도 하나님의 영광을 가볍게 여기는 근본적인 변화에서 출발해야 한다는 논지입니다.","그는 이 교환이 생각의 헛됨과 마음의 어두움, 자신을 지혜롭다고 착각하는 태도를 낳는다고 설명합니다. 하나님을 향하도록 만들어진 마음이 하나님의 영광을 다른 것으로 바꾸면 눈앞의 피조물을 잘못된 기준으로 해석하게 됩니다. 파이퍼에게 우상숭배에서 벗어난다는 것은 삶의 즐거움을 모두 지워 버리는 일이 아니라, 피조물의 선함을 인정하면서도 그 근원이신 창조주의 영광을 가장 크게 여기는 삶으로 돌아가는 것입니다.","원어·해석 보충","‘진노가 드러난다’(ἀποκαλύπτεται)는 1:17의 ‘하나님의 의가 드러난다’와 언어적으로 연결됩니다. ‘바꾸었다’(ἤλλαξαν/μετήλλαξαν)의 반복과 ‘내버려 두셨다’(παρέδωκεν)의 세 차례 반복이 단락의 구조를 만듭니다. 26–27절의 성행위 관련 구절은 역사적 문맥, 성경 전체의 성 윤리 및 교회 내 해석 차이를 신중하게 검토해야 하며, 사람을 모욕하거나 비인간화하는 표현에 이용하지 않습니다. 32절 뒤의 2:1은 이 진단을 남에게 적용하며 자신을 예외로 두는 독자를 직접 경고합니다."]}],"sources":[{"author":"The Gospel Coalition","title":"romans","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/romans/"},{"author":"John Piper","title":"the wrath of god against holding down the truth","kind":"설교","url":"https://www.desiringgod.org/messages/the-wrath-of-god-against-holding-down-the-truth"},{"author":"John Piper","title":"the first dark exchange idolatry","kind":"설교","url":"https://www.desiringgod.org/messages/the-first-dark-exchange-idolatry"}],"preview":false,"unit_type":"DEEP"},{"id":"EPI-004","track":"EPI","title":"하나님의 의로운 심판","passage":"롬 2:1–16","excerpt":"다른 사람을 판단하는 인간은 왜 자신도 죄 아래 있는가?","bible":"https://www.bible.com/ko/bible/142/ROM.2.RNKSV","verses":[],"sections":[{"heading":"오늘의 질문","paragraphs":["남의 죄를 정확히 지적할 수 있다면, 그것만으로 자신이 하나님 앞에서 의롭다는 뜻일까요?","본문 전체 읽기","로마서 2:1–16: https://www.bible.com/ko/bible/142/ROM.2.RNKSV","앞 본문: 롬 1:18–32. 다음 본문: 롬 2:17–29. 전체 논증의 결론: 롬 3:9–26.","배경과 맥락","로마서 1장 후반에서 바울은 하나님을 거부한 인간의 우상숭배와 그 결과를 설명했습니다. 독자는 그런 행동을 비난하는 입장에 쉽게 설 수 있습니다. 그러나 2장은 바로 그 판단하는 사람에게 말을 돌립니다. 유대인과 이방인이 함께 모였던 로마 교회의 상황에서 바울은 하나님의 심판이 사람의 집단 정체성이나 남을 판단하는 능력에 좌우되지 않음을 밝힙니다."]},{"heading":"본문을 깊이 읽기","paragraphs":["첫째, 남을 판단하는 사람도 하나님의 판결을 피할 수 없습니다(1–5절). 바울의 요지는 타인의 악을 악이라고 말해서는 안 된다는 뜻이 아닙니다. 문제는 자신도 같은 종류의 악을 행하면서 다른 사람에게만 심판을 선언하는 위선입니다. 하나님의 오래 참으심을 무시하고 그동안 무사했으니 자신이 무죄라고 생각하는 것은 잘못입니다. 바울은 하나님의 인자하심이 회개로 이끄신다고 말합니다. 심판이 당장 나타나지 않는 시간을 자기 의의 증거로 삼지 말고 돌이킬 기회로 받아들여야 합니다.","둘째, 하나님의 판단에는 편애가 없습니다(6–11절). 바울은 하나님이 각 사람의 행위대로 갚으신다고 설명하면서 인내하며 선을 추구하는 사람과 악에 순종하는 사람의 다른 결말을 대비합니다. 그리고 유대인에게 먼저, 헬라인에게도 같은 원칙이 적용된다고 말합니다. 이 구절을 로마서 전체에서 떼어 놓으면 구원을 자신의 선행으로 사는 방법처럼 읽을 수 있습니다. 그러나 바울은 곧 모든 사람이 죄 아래 있으며, 오직 그리스도를 통한 하나님의 의가 필요한 이유를 설명합니다. 행위에 대한 심판의 실제성과 은혜로 의롭다 하시는 복음은 바울의 전체 논증 안에서 함께 읽어야 합니다.","셋째, 율법을 가진 것과 율법에 순종하는 것은 다릅니다(12–16절). 바울은 율법을 듣기만 한 사람보다 그 말씀을 실천하는 사람을 말합니다. 또한 율법을 직접 받지 못한 이방인에게서도 양심이 고발하거나 변호하는 모습을 이야기합니다. 여기서 14–15절의 이방인이 일반 인류를 가리키는지, 성령의 새 마음을 받은 이방인 그리스도인을 특별히 염두에 두는지 복음주의 해석 사이에도 차이가 있습니다. 두 관점 모두 바울이 하나님의 심판 앞에서 ‘우리 집단은 안전하다’는 자랑을 무너뜨리고 있다는 점을 놓치지 않습니다. 마지막에 바울은 하나님이 예수 그리스도를 통하여 사람들의 은밀한 것까지 판단하실 것이라고 선언합니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 외적인 종교적 지위나 사람들 앞의 평가로 판단하지 않으십니다. 그분은 마음과 감추어진 일을 아시며, 회개하도록 인내와 인자함을 베푸십니다. 이 말씀을 받은 사람에게 필요한 첫 응답은 다른 사람을 더 정확하게 판단하는 기술이 아니라, 복음 앞에 자신도 죄인으로 서는 겸손입니다. 예수님이 왜 필요하신지 점점 더 분명해집니다.","주요 절","2:4 하나님의 인자하심은 죄에 대한 무관심이 아니라 회개의 기회를 주시는 오래 참으심입니다.","2:11 하나님의 심판에는 사람에 따른 편애가 없다는 바울의 원칙입니다.","2:13–16 실천, 양심, 마음의 판단을 다루는 절로서 3장의 칭의 논증과 함께 검토해야 합니다."]},{"heading":"깊이 읽기 | 신앙의 선배들에게 배우기","paragraphs":["도니 레이 매시스(Donny Ray Mathis II), 「Romans」, The Gospel Coalition Bible Commentary, 2:1–16.","매시스는 1:18–32에서 비판을 받던 사람들을 보고 스스로 안전하다고 느낄 독자를 바울이 다시 겨냥한다고 설명합니다. 특별히 율법을 받은 유대인의 자랑이 문맥상 중요한 대상으로 보이지만, 바울은 ‘판단하는 모든 사람’이라는 표현으로 그 문제를 더 넓힙니다. 매시스는 하나님의 인자하심을 회개의 기회로 해설하고, 그 기회를 악용하여 자기 위선을 합리화하는 것이 오히려 심판을 쌓는 행동이라고 설명합니다.","그의 해설에서 12–16절은 신약학적 논의가 많은 부분입니다. 매시스는 14–15절의 이방인을 그리스도로 새롭게 된 이방인 신자들로 해석하는 견해를 발전시킵니다. 그들의 변화된 삶이 율법의 요구를 마음에 담은 하나님의 백성임을 드러낸다는 것입니다. 다른 복음주의 주석에서는 이 절을 일반적인 이방인들의 양심과 도덕적 책임을 서술한 문장으로 읽습니다. 원문이 하나의 상세한 이론을 명시한다고 단정하기보다, 매시스가 왜 그렇게 읽는지 바울의 ‘듣는 자와 행하는 자’, 유대인과 이방인, 그리스도 안에서의 심판이라는 연결로 살필 필요가 있습니다. 어쨌든 바울은 유대인과 이방인 모두 자기 집단과 지식을 내세울 수 없게 만들며, 의롭고 공정하신 하나님 앞에 세웁니다.","원전: https://www.thegospelcoalition.org/commentary/romans/"]},{"heading":"묵상 질문","paragraphs":["1. 내가 다른 사람의 죄를 판단하면서 내게 베푸신 하나님의 오래 참으심을 잊지는 않았습니까?","2. ‘율법을 듣는 일’과 ‘그 말씀을 행하는 일’의 차이를 지금의 내 신앙생활에서 어떻게 발견합니까?"]},{"heading":"기도","paragraphs":["공의로우시고 인자하신 하나님, 다른 사람을 향한 판단으로 저 자신을 의롭다 여기지 않게 하소서. 주님의 오래 참으심을 회개의 기회로 받아들이고, 예수 그리스도의 은혜를 구하며 그 말씀을 삶에서 실천하게 하소서. 아멘."]}],"sources":[{"author":"The Gospel Coalition","title":"romans","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/romans/"}],"preview":false,"unit_type":"DEEP"},{"id":"PSA-R70-001","track":"PSA","title":"여호와의 율법을 즐거워하는 사람","passage":"시 1:1–6","excerpt":"복된 삶은 무엇에 뿌리를 내리는가?","bible":"https://www.bible.com/ko/bible/142/PSA.1.RNKSV","verses":[{"n":1,"text":"복 있는 사람은 악인들의 조언을 따라 걷지 않고, 죄인들의 길에 서지 않으며, 비웃는 자들의 자리에 앉지 않는다."},{"n":2,"text":"오히려 여호와의 가르침을 기뻐하고, 그 가르침을 밤낮으로 되새긴다."},{"n":3,"text":"그는 물길 곁에 심긴 나무와 같다. 철을 따라 열매를 맺고 잎사귀가 마르지 않는다. 그가 하는 일이 형통하다."},{"n":4,"text":"그러나 악인들은 그렇지 않다. 그들은 바람에 날리는 겨와 같다."},{"n":5,"text":"그러므로 악인들은 심판 가운데 서지 못하고 죄인들은 의인들의 모임에 들지 못한다."},{"n":6,"text":"여호와께서는 의인들의 길을 아시지만, 악인들의 길은 멸망한다."}],"sections":[{"heading":"오늘의 질문","paragraphs":["시편 150편의 기도와 찬송은 왜 ‘복 있는 사람의 길’과 ‘여호와의 가르침을 즐거워하는 마음’으로 시작할까요?"]},{"heading":"본문을 깊이 읽기 | 어떤 목소리가 내 삶을 이끄는가","paragraphs":["시편 1편은 어떤 위기나 사건을 배경으로 하소연하는 기도가 아닙니다. 시편 전체를 읽기 전에 우리를 하나님의 말씀 앞으로 세우는 문입니다. 이 시는 두 종류의 사람을 나열하기보다 서로 다른 두 길을 대비합니다. 한 길은 악인의 조언, 죄인의 삶, 비웃는 자들의 자리에 차츰 익숙해지는 길입니다. 다른 길은 여호와의 가르침을 즐거워하며 그 말씀을 마음으로 되새기는 길입니다. 무엇을 들으며, 무엇을 사랑하며, 어디에 머무는지가 한 사람의 삶을 빚습니다.","첫째, 복은 나쁜 행동을 피하는 소극적인 경계만으로 설명되지 않습니다(1–2절). 시인은 ‘걷다, 서다, 앉다’라는 일상의 움직임으로 사람이 잘못된 생각과 태도에 정착해 가는 위험을 그립니다. 그러나 중요한 반전은 2절의 ‘오히려’입니다. 이 사람의 마음은 단지 악을 미워하는 데 머물지 않고 여호와의 가르침을 즐거워합니다. 명령을 억지로 외우는 일을 넘어, 하나님이 말씀하시는 것을 좋은 것으로 여기고 그분의 뜻을 기억합니다. 마음이 어디에서 기쁨을 찾느냐가 길의 방향을 바꿉니다.","둘째, 말씀을 즐거워하는 사람은 물길 곁에 심긴 나무에 비유됩니다(3절). 열매를 맺는 때가 있으며, 마르지 않는 잎이 있습니다. ‘형통하다’는 말을 언제나 돈을 벌고 병을 피하며 실패하지 않는다는 약속으로 읽어서는 안 됩니다. 실제 시편은 곧이어 다윗의 도피와 고난, 억울한 자의 탄식으로 가득합니다. 나무의 생명력은 고난이 없어서가 아니라 깊은 물의 근원과 연결되어 있다는 데 있습니다. 하나님은 자신의 말씀을 통해 자기 백성을 살리시며, 마땅한 때에 열매를 맺게 하십니다.","셋째, 이 두 길의 차이는 마지막 심판 앞에서 온전히 드러납니다(4–6절). 물가의 나무와 달리 악인들은 바람에 흩어지는 겨와 같습니다. 무엇이 오래 남는 삶이며 무엇이 결국 무너질 삶인지를 하나님이 판단하십니다. 시편은 우리의 현재 형편만으로 복과 저주를 섣불리 가르지 않습니다. 마지막 구절은 의인들의 길을 여호와가 ‘아신다’고 말합니다. 하나님의 백성이 붙드는 안전은 자신이 만들어 낸 성공보다 자신을 아시는 하나님의 신실한 돌보심에 있습니다."]},{"heading":"말씀에서 만나는 하나님","paragraphs":["하나님은 단지 규칙을 주어 사람을 평가하시는 분이 아닙니다. 자기 말씀을 주셔서 길을 가르치시고, 그 길을 아시며, 마침내 공의롭게 판단하시는 분입니다. 우리는 이 시를 읽으며 완벽한 의인이라는 자격을 자랑할 수 없습니다. 그리스도인은 하나님의 말씀에 온전히 순종하신 예수 그리스도를 바라보면서, 그분의 은혜 안에서 하나님의 말씀을 기뻐하고 삶으로 응답하는 길을 배웁니다."]},{"heading":"묵상 질문","paragraphs":["1. 하루의 생각을 가장 오래 이끄는 목소리는 무엇입니까? 그것은 하나님의 말씀과 어떻게 관계가 있습니까?","2. 나는 말씀을 나의 성공을 보장하는 공식으로 읽습니까, 아니면 하나님을 알고 사랑하게 하는 생명의 말씀으로 읽습니까?"]},{"heading":"기도","paragraphs":["여호와 하나님, 제 마음이 세상의 헛된 약속보다 주님의 말씀을 더 기뻐하게 하소서. 말씀을 잊지 않고 되새기며, 열매가 보이지 않는 때에도 저를 아시는 주님의 신실하심을 신뢰하게 하소서. 예수님의 이름으로 기도합니다. 아멘."]},{"heading":"깊이 읽기 | 설교와 주석의 논증","paragraphs":["존 파이퍼 — “Meditate on the Word of the Lord Day and Night” (1999)","파이퍼는 왜 시편의 기도 책이 기도가 아닌 ‘말씀을 즐거워하는 사람’의 이야기로 시작하는지 질문하며 설교를 엽니다. 그의 답은 말씀과 기도가 서로 분리되어 존재하지 않는다는 데 있습니다. 하나님의 말씀은 기도를 불러일으킵니다. 하나님의 명령과 약속을 듣게 함으로써 기도할 이유와 용기를 줍니다. 또한 말씀은 기도의 내용을 가르칩니다. 우리가 하나님의 성품과 뜻을 알수록 단지 자신의 소원만 나열하지 않고 하나님이 기뻐하시는 것을 구합니다. 마지막으로 파이퍼는 기도가 삶 가운데 말씀을 실천하도록 사람을 움직인다고 설명합니다. 성령께 의지하는 기도와 말씀을 통한 실제 순종은 따로 떨어질 수 없습니다.","그가 3절의 나무를 설명하는 방식도 중요합니다. 열매를 맺는 삶은 다른 사람을 살리는 생명력이 있으며, 잎이 마르지 않는 삶은 고난이나 메마름이 와도 깊은 근원에서 힘을 얻는 삶입니다. ‘형통’을 무조건적인 물질적 번영으로 해석하지 않고 4–6절의 심판과 영원한 결과를 기준으로 읽습니다. 그는 시편 73편, 하박국 3장과 연결해 의인도 괴로움을 겪지만 하나님의 말씀에 뿌리를 두었기에 끝내 열매를 맺을 수 있다고 설명합니다. 파이퍼에게 묵상은 성경 구절을 기억하고 마음으로 반복해 기도와 행동에 스며들게 하는 일입니다. 그리고 그렇게 말씀을 즐거워할 마음 자체를 하나님께 구하라고 권면합니다.","브루스 K. 왈트키 — “Psalms 1–41”, The Gospel Coalition Bible Commentary","왈트키는 시편 1–2편이 시편집 전체의 서문 역할을 한다는 큰 문학적 틀에서 1편을 읽습니다. 시편 1편은 말씀을 사랑하는 의인의 길과 악인의 길을 대조하고, 시편 2편은 여호와의 기름부음 받은 왕에게 복종하라는 요청으로 이어집니다. 이렇게 하나님의 가르침과 하나님이 세우신 왕에 대한 응답은 시편 전체의 중심 질문을 준비합니다.","왈트키는 첫 세 절의 구조에서 ‘복 있는 사람’이 무엇을 하지 않는지를 보여 주는 1절보다, 그 마음이 어디에 기쁨을 두는지 설명하는 2절에 주목합니다. 그리고 3절의 나무와 4절의 겨를 대비하여 생명의 근원과 사라질 삶의 방향을 설명합니다. 특히 마지막 6절의 ‘길’이라는 표현은 사람의 마음, 삶의 행동, 결과를 한꺼번에 나타냅니다. 하나님이 ‘의인의 길을 아신다’는 사실이 시의 마지막 근거가 됩니다. 왈트키는 역사적 의미에서 하나님의 가르침을 기뻐하는 사람의 모습을 존중하면서도, 그 길이 예수 그리스도 안에서 온전히 드러난다는 정경적 연결을 제시합니다.","원어와 문학적 구조","2절 ‘가르침’은 토라(תּוֹרָה)로, 하나님께서 주시는 교훈·인도를 포함하는 표현입니다. ‘묵상하다’(הָגָה)는 낮게 말하며 되새기는 이미지를 가집니다.","1절 걷다–서다–앉다와 3–4절 나무–겨, 6절 두 갈래 길은 시편을 가로지르는 시적 대조입니다.","형통(3절)을 오직 지금 당장의 재산·지위·건강의 보장으로 읽는 해석은 고난과 심판을 함께 다루는 시편 전체의 문맥과 맞지 않습니다."]}],"sources":[{"author":"John Piper","title":"meditate on the word of the lord day and night","kind":"설교","url":"https://www.desiringgod.org/messages/meditate-on-the-word-of-the-lord-day-and-night"},{"author":"The Gospel Coalition","title":"psalm 1 psalm 41","kind":"주석","url":"https://www.thegospelcoalition.org/commentary/psalm-1-psalm-41/"}],"preview":false,"unit_type":"DEEP"}]};


(function(){
"use strict";
const KEY="dailyword.reader.v2";const allowedIds=new Set(DATA.entries.map(x=>x.id));
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const all=()=>DATA.entries,byId=id=>all().find(x=>x.id===id),tracks=()=>DATA.tracks;
const safeProfile=p=>({name:String(p?.name||"나").slice(0,35),completed:Array.isArray(p?.completed)?[...new Set(p.completed.filter(x=>allowedIds.has(x)))]:[],favorites:Array.isArray(p?.favorites)?[...new Set(p.favorites.filter(x=>allowedIds.has(x)))]:[],last:allowedIds.has(p?.last)?p.last:"",lastByTrack:Object.fromEntries(Object.entries(p?.lastByTrack||{}).filter(([t,id])=>tracks().some(x=>x.id===t)&&allowedIds.has(id))),updated:typeof p?.updated==="string"?p.updated:""});
let state=(()=>{try{let x=JSON.parse(localStorage.getItem(KEY));if(x&&x.version===2&&x.profiles&&Object.keys(x.profiles).length)return x;}catch{}return{version:2,active:"default",profiles:{default:{name:"나",completed:[],favorites:[],last:"",updated:""}}};})();
if(!state.profiles[state.active])state.active=Object.keys(state.profiles)[0];
let font=Number(localStorage.getItem("dailyword.fontsize")||"16");if(font<14||font>24||!Number.isFinite(font))font=16;
let view="home",activeTrack="JES",readingId="",search="";
const current=()=>state.profiles[state.active],save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}};
function route(){const p=new URLSearchParams(location.search);const r=p.get("read"),t=p.get("track"),v=p.get("view");if(r&&byId(r)){view="reader";readingId=r;}else if(t&&tracks().some(x=>x.id===t)){view="track";activeTrack=t;}else if(v==="history"){view="history";}else{view="home";}}
function navigate(v,arg){view=v;if(v==="reader"){readingId=arg;if(!byId(arg))return;current().last=arg;current().lastByTrack=current().lastByTrack||{};current().lastByTrack[byId(arg).track]=arg;current().updated=new Date().toISOString();save();if(typeof window.DWOnLocalChange==='function')window.DWOnLocalChange({kind:'open',track:byId(arg).track,sessionId:arg});}if(v==="track")activeTrack=arg;const p=v==="reader"?"?read="+encodeURIComponent(arg):v==="track"?"?track="+encodeURIComponent(arg):v==="history"?"?view=history":location.pathname;history.pushState({},'',p);render();window.scrollTo(0,0);}
const completed=id=>current().completed.includes(id),favorite=id=>current().favorites.includes(id);
const pill=(text)=>'<span class="q-pill">'+esc(text)+'</span>';
const progress=t=>{const total=DATA.entries.filter(e=>e.track===t).length;const done=DATA.entries.filter(e=>e.track===t&&completed(e.id)).length;return{done,total};};
function header(){return '<header class="q-top"><button class="q-brand" data-go="home">✣ 매일 말씀</button><div class="q-header-actions"><button class="q-toplink" data-go="history">내 기록</button><button class="q-profile" data-go="history">'+esc(current().name)+' ▾</button></div></header>';}
function footer(){return '<nav class="q-bottom"><button data-go="home" class="'+(view==="home"?"on":"")+'">홈</button><button data-go="track" data-id="'+esc(activeTrack)+'" class="'+(view==="track"?"on":"")+'">목록</button><button data-go="history" class="'+(view==="history"?"on":"")+'">내 기록</button></nav>';}
function card(entry){return '<button class="q-entry" data-go="reader" data-id="'+esc(entry.id)+'"><span class="q-kicker">'+esc(tracks().find(t=>t.id===entry.track)?.name)+'</span><strong>'+esc(entry.title)+'</strong><span>'+esc(entry.passage)+'</span><small>'+ (completed(entry.id)?'✓ 읽음':"본문과 묵상 읽기")+'</small></button>';}
function home(){const last=byId(current().last)||all()[0];return '<section class="q-container"><div class="q-eyebrow">MY DAILY DEVOTION</div><h1>말씀을 따라, 계속 읽어갑니다</h1><p class="q-sub">날짜가 지나도 묵상은 사라지지 않습니다. 다섯 트랙 가운데 원하는 곳에서 다시 시작하세요.</p><div class="q-resume"><div><span>이어서 읽기</span><h2>'+esc(last.title)+'</h2><p>'+esc(last.passage)+' · '+esc(tracks().find(t=>t.id===last.track)?.name)+'</p></div><button class="q-primary" data-go="reader" data-id="'+esc(last.id)+'">읽기 계속 →</button></div><h2 class="q-title">말씀 트랙</h2><div class="q-tracks">'+tracks().map(t=>{const p=progress(t.id),lastSession=byId(current().lastByTrack?.[t.id]);return '<button class="q-track" data-go="track" data-id="'+t.id+'"><span class="q-track-index">0'+(t.order+1)+'</span><strong>'+esc(t.name)+'</strong><small>'+esc(t.description)+'</small>'+(lastSession?'<small class="q-track-resume">최근: '+esc(lastSession.title)+'</small>':'')+'<span class="q-track-counter">'+p.done+' / '+p.total+' 읽음 <b>→</b></span></button>';}).join('')+'</div><h2 class="q-title">지금 읽을 수 있는 묵상</h2><div class="q-entrygrid">'+all().map(card).join('')+'</div><p class="q-disclaimer">공개된 묵상 원고를 읽어보세요. 검수가 끝난 새 원고를 차례로 추가합니다.</p></section>';}
function track(){const t=tracks().find(t=>t.id===activeTrack);const list=DATA.index.filter(x=>x.track===activeTrack).sort((a,b)=>{const pa=a.phase==="INTRO"?0:a.phase==="MAIN"?1:2,pb=b.phase==="INTRO"?0:b.phase==="MAIN"?1:2;return pa-pb||a.sequence-b.sequence;});const p=progress(activeTrack);return '<section class="q-container"><button class="q-back" data-go="home">← 전체 트랙</button><p class="q-eyebrow">READING TRACK</p><h1>'+esc(t.name)+'</h1><p class="q-sub">'+esc(t.description)+'</p><div class="q-track-progress">'+p.done+'편 읽음 / 공개된 '+p.total+'편 · 전체 계획 '+list.length+'개 회차</div><div class="q-list">'+list.map((x,i)=>{const publicItem=byId(x.id);return publicItem?'<button class="q-list-row" data-go="reader" data-id="'+esc(x.id)+'"><span>'+String(i+1).padStart(2,"0")+'</span><div><strong>'+esc(x.title)+'</strong><small>'+esc(x.passage)+'</small></div><em>'+(completed(x.id)?'✓ 읽음':'읽기 →')+'</em></button>':'<div class="q-list-row q-locked"><span>'+String(i+1).padStart(2,"0")+'</span><div><strong>'+esc(x.title)+'</strong><small>'+esc(x.passage)+'</small></div><em>준비 중</em></div>';}).join('')+'</div><div class="q-subnote">‘준비 중’인 원고는 검수 후 공개합니다. 오래된 회차도 이 목록에서 다시 열 수 있습니다.</div></section>';}
function reader(){const e=byId(readingId);if(!e)return home();const allEntries=all(),idx=allEntries.findIndex(x=>x.id===e.id),siblings=allEntries.filter(x=>x.track===e.track),si=siblings.findIndex(x=>x.id===e.id),prev=siblings[si-1]||allEntries[idx-1],next=siblings[si+1]||allEntries[idx+1];const q=e.sections;
const paragraphs=q.map(s=>'<section class="q-section" id="section-'+esc(s.heading)+'"><h2>'+esc(s.heading)+'</h2>'+(s.paragraphs||[]).map(text=>'<p>'+esc(text)+'</p>').join('')+'</section>').join('');
const sourceHTML='<section class="q-section q-sources"><h2>신앙의 선배들에게 배우기 · 관련 자료</h2><p>원문을 확인할 수 있는 복음주의 자료를 연결했습니다. 설교자의 해석과 성경 본문 자체의 진술은 구별합니다.</p>'+e.sources.map(s=>'<a href="'+esc(s.url)+'" rel="noopener noreferrer" target="_blank"><span>'+esc(s.kind)+' · '+esc(s.author)+'</span><strong>'+esc(s.title)+'</strong><span>원문 열기 ↗</span></a>').join('')+'</section>';
const scripture=e.verses.map(v=>'<p class="q-verse"><sup>'+v.n+'</sup>'+esc(v.text)+'</p>').join('');
return '<article class="q-reader"><button class="q-back" data-go="track" data-id="'+e.track+'">← '+esc(tracks().find(t=>t.id===e.track)?.name)+' 목록</button><div class="q-reading-head"><span class="q-kicker">성경 묵상 · 발행 원고</span><h1>'+esc(e.title)+'</h1><p>'+esc(e.passage)+'</p></div><div class="q-reading-toolbar"><span>본문과 강해를 천천히 읽어보세요</span><div><button data-font="-1">A−</button><button data-font="1">A+</button><button data-mark="'+e.id+'">'+(completed(e.id)?'✓ 읽음':'읽음 표시')+'</button><button data-fav="'+e.id+'">'+(favorite(e.id)?'★ 저장':'☆ 즐겨찾기')+'</button></div></div><div class="q-reading-body" style="--text-size:'+font+'px"><section class="q-scripture"><div class="q-kicker">'+(e.verses.length?'성경 본문 · 자체 직역':'성경 본문 · 직접 읽기')+'</div><h2>'+esc(e.passage)+'</h2>'+(e.verses.length?'<p class="q-scripture-note">공인 번역본이 아닌 원문 기반 자체 직역입니다.</p>':'<p class="q-scripture-note">성경 앱에서 본문 전문을 읽으세요. 아래는 본문 안내와 해설입니다.</p>')+''+scripture+'<p class="q-bible-link"><a href="'+esc(e.bible)+'" rel="noopener noreferrer" target="_blank">성경 앱으로 비교 읽기 ↗</a></p></section>'+paragraphs+sourceHTML+'</div><div class="q-reader-tail"><button data-mark="'+e.id+'">'+(completed(e.id)?'✓ 읽기 완료':'이 회차 읽기 완료')+'</button><p>읽음 기록은 현재 기기 안에 저장됩니다.</p></div><div class="q-pager"><button '+(prev?'data-go="reader" data-id="'+prev.id+'"':'disabled')+'><small>이전 묵상</small><strong>'+(prev?esc(prev.title):'첫 번째 원고')+'</strong></button><button '+(next?'data-go="reader" data-id="'+next.id+'"':'disabled')+'><small>다음 묵상</small><strong>'+(next?esc(next.title):'마지막 원고')+'</strong></button></div><p class="q-next-note">이전·다음 버튼은 공개된 원고를 기준으로 이동합니다.</p></article>';}
function historyPage(){const p=current();const done=all().filter(e=>completed(e.id));const fav=all().filter(e=>favorite(e.id));return '<section class="q-container"><p class="q-eyebrow">YOUR LIBRARY</p><h1>내 읽기 기록</h1><p class="q-sub">ID 동기화를 연결하면 다른 휴대폰에서도 같은 ID로 이어 읽을 수 있습니다. 연결 전에는 이 기기에만 저장되며 백업 파일로 옮길 수 있습니다.</p><div id="dw-sync-root"></div><div class="q-profile-pane"><strong>이 기기에서 사용하는 ID</strong><div class="q-profile-pills">'+Object.entries(state.profiles).map(([id,v])=>'<button data-profile="'+esc(id)+'" class="'+(state.active===id?'active':'')+'">'+esc(v.name)+'</button>').join('')+'</div><div class="q-add-profile"><input id="q-new-profile" maxlength="35" placeholder="다른 ID (기기 내 기록용)"/><button data-action="add-profile">기기 내 ID 추가</button></div><p class="q-tiny">기기 내 ID는 자동 동기화되지 않습니다. ‘내 ID’ 동기화 연결을 사용하세요. 다른 사람과 같은 기기를 사용할 때 기록을 구분하기 위한 기능입니다.</p></div><div class="q-record-grid"><div><strong>'+done.length+'편</strong><span>읽음 완료</span></div><div><strong>'+fav.length+'편</strong><span>즐겨찾기</span></div></div><h2 class="q-title">이어 읽기</h2>'+(byId(p.last)?card(byId(p.last)):'<p>아직 읽기 기록이 없습니다.</p>')+'<h2 class="q-title">읽은 원고</h2><div class="q-entrygrid">'+(done.length?done.map(card).join(''):'<p>읽은 원고에 표시하면 여기에 쌓입니다.</p>')+'</div><h2 class="q-title">기록 옮기기</h2><div class="q-export"><button data-action="export">기록 파일 내보내기</button><button data-action="import">기록 파일 가져오기</button><input type="file" id="q-import-file" accept=".json,application/json" hidden/><p>내보내기 파일에는 이 기기의 ID 표시값과 읽기·즐겨찾기 기록이 들어갑니다. 신뢰하는 기기에만 옮겨주세요.</p></div></section>';}
function render(){document.title=(view==="reader"&&byId(readingId)?byId(readingId).title+' | ':'')+'매일 말씀';const root=document.getElementById("app");root.innerHTML=header()+(view==="reader"?reader():view==="track"?track():view==="history"?historyPage():home())+footer();if(typeof window.DWRenderSync==="function")window.DWRenderSync();}
window.DailyWordLocalAPI={
  active:()=>state.active,
  current:()=>safeProfile(current()),
  activateCloud:(name,remote)=>{
    const id="cloud_"+Array.from(name.toLowerCase()).map(ch=>ch.codePointAt(0).toString(36)).join("_");
    state.profiles[id]=safeProfile({...remote,name});
    state.active=id;save();render();return id;
  },
  refresh:()=>render()
};
function makeProfile(){const name=document.getElementById("q-new-profile")?.value.trim().slice(0,35);if(!name)return;let id="p"+Date.now().toString(36)+Math.random().toString(36).slice(2,6);state.profiles[id]={name,completed:[],favorites:[],last:"",updated:""};state.active=id;save();render();}
function toggle(list,id){const p=current();p[list]=p[list].includes(id)?p[list].filter(x=>x!==id):[...p[list],id];p.updated=new Date().toISOString();save();if(typeof window.DWOnLocalChange==='function')window.DWOnLocalChange({kind:list==='completed'?'mark':'favorite',sessionId:id,value:p[list].includes(id)});render();}
function exportJSON(){const obj={app:"daily-word-qt",version:2,exportedAt:new Date().toISOString(),profiles:state.profiles};const blob=new Blob([JSON.stringify(obj,null,2)],{type:"application/json"});const u=URL.createObjectURL(blob);const a=document.createElement("a");a.href=u;a.download="매일말씀_읽기기록_"+new Date().toISOString().slice(0,10)+".json";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),500);}
async function importJSON(file){if(!file||file.size>300000)return alert("기록 파일이 너무 크거나 올바르지 않습니다.");try{const obj=JSON.parse(await file.text());if(obj.app!=="daily-word-qt"||obj.version!==2||typeof obj.profiles!=="object"||!obj.profiles)throw Error("형식 불일치");const entries=Object.entries(obj.profiles);if(entries.length===0||entries.length>100)throw Error("프로필 수 초과");if(!confirm(entries.length+"개의 프로필 기록을 현재 기기에 합치시겠습니까?"))return;for(const [id,raw] of entries){if(!/^[\w-]{1,64}$/.test(id))continue;const inp=safeProfile(raw),old=state.profiles[id];if(old){old.completed=[...new Set([...old.completed,...inp.completed])];old.favorites=[...new Set([...old.favorites,...inp.favorites])];if(inp.last)old.last=inp.last;old.name=inp.name;}else state.profiles[id]=inp;}save();render();alert("기록 가져오기를 완료했습니다.");}catch(e){alert("기록 파일을 읽지 못했습니다: "+e.message);}}
document.addEventListener("click",e=>{const b=e.target.closest("[data-go],[data-mark],[data-fav],[data-font],[data-action],[data-profile]");if(!b)return;if(b.dataset.go){navigate(b.dataset.go,b.dataset.id);}else if(b.dataset.mark){toggle("completed",b.dataset.mark);}else if(b.dataset.fav){toggle("favorites",b.dataset.fav);}else if(b.dataset.font){font=Math.max(14,Math.min(24,font+Number(b.dataset.font)));localStorage.setItem("dailyword.fontsize",String(font));render();}else if(b.dataset.profile){state.active=b.dataset.profile;save();render();if(typeof window.DWOnProfileChange==="function")window.DWOnProfileChange();}else if(b.dataset.action==="add-profile")makeProfile();else if(b.dataset.action==="export")exportJSON();else if(b.dataset.action==="import")document.getElementById("q-import-file")?.click();});
document.addEventListener("change",e=>{if(e.target?.id==="q-import-file")importJSON(e.target.files?.[0]);});
window.addEventListener("popstate",()=>{route();render();});
if(localStorage.getItem("qt_read_INT-001")==="yes"&&!state.profiles.default.completed.includes("INT-001")){state.profiles.default.completed.push("INT-001");save();}
route();render();
})();
